    pub fn allocate_node_graph_id(&self) -> NodeGraphId {
        self.next_node_graph_id.fetch_add(1, Ordering::Relaxed)
    }

    pub fn upsert_node_graph(&self, graph: NodeGraphSummary) -> Result<(), String> {
        let (ack, receiver) = mpsc::sync_channel(1);
        self.send(EngineCommand::UpsertNodeGraphPublished {
            graph,
            expires_at: Instant::now() + Duration::from_secs(2),
            ack,
        })
        .map_err(|error| error.to_string())?;
        receiver
            .recv_timeout(Duration::from_secs(3))
            .map_err(|error| format!("Node graph save acknowledgement failed: {error}"))?
    }

    pub fn set_node_graph_enabled(
        &self,
        graph_id: NodeGraphId,
        enabled: bool,
    ) -> Result<(), String> {
        let (ack, receiver) = mpsc::sync_channel(1);
        self.send(EngineCommand::SetNodeGraphEnabledPublished {
            graph_id,
            enabled,
            expires_at: Instant::now() + Duration::from_secs(2),
            ack,
        })
        .map_err(|error| error.to_string())?;
        receiver
            .recv_timeout(Duration::from_secs(3))
            .map_err(|error| format!("Node graph enable acknowledgement failed: {error}"))?
    }

    pub fn remove_node_graph(&self, graph_id: NodeGraphId) -> Result<(), String> {
        let (ack, receiver) = mpsc::sync_channel(1);
        self.send(EngineCommand::RemoveNodeGraphPublished {
            graph_id,
            expires_at: Instant::now() + Duration::from_secs(2),
            ack,
        })
        .map_err(|error| error.to_string())?;
        receiver
            .recv_timeout(Duration::from_secs(3))
            .map_err(|error| format!("Node graph removal acknowledgement failed: {error}"))?
    }

    pub fn allocate_stage_object_id(&self) -> StageObjectId {
        self.next_stage_object_id.fetch_add(1, Ordering::Relaxed)
    }

    pub fn send(&self, command: EngineCommand) -> Result<(), EngineError> {
        if let EngineCommand::ClearLiveAudioInput { generation }
        | EngineCommand::ClearLiveAudioInputPublished { generation, .. } = &command
        {
            self.shared_telemetry.request_live_audio_clear(*generation);
        }
        self.sync_allocator_counters_for_command(&command);
        match self.queue.push(QueuedEngineCommand {
            command,
            queued_at: Instant::now(),
        }) {
            Ok(()) => {
                self.wake.notify_command();
                Ok(())
            }
            Err(_) => {
                self.shared_telemetry.record_queue_push_failure();
                Err(EngineError::QueueFull)
            }
        }
    }

    pub fn clear_live_audio_input(&self, generation: u64) -> Result<(), String> {
        let (ack, receiver) = mpsc::sync_channel(1);
        self.send(EngineCommand::ClearLiveAudioInputPublished {
            generation,
            expires_at: Instant::now() + Duration::from_secs(2),
            ack,
        })
        .map_err(|error| error.to_string())?;
        receiver
            .recv_timeout(Duration::from_secs(3))
            .map_err(|error| format!("Live audio clear acknowledgement failed: {error}"))?
    }

