#[derive(Clone)]
enum PendingCommandRollback {
    KeepApplied,
    RestoreTouchSurface {
        touch_surface: TouchSurfaceSummary,
        last_error: Option<String>,
    },
    ClearBootstrappedVjShow,
    RemoveAddedEffect {
        effect_id: EffectId,
        last_error: Option<String>,
    },
    RestoreEffect {
        index: Option<usize>,
        effect: Option<RuntimeEffect>,
        timeline_events: Option<Vec<RuntimeTimelineEvent>>,
        last_error: Option<String>,
    },
    RestoreEffectEnabled {
        effect_id: EffectId,
        enabled: bool,
        last_error: Option<String>,
    },
    RestoreNodeGraphs {
        node_graphs: Vec<RuntimeNodeGraph>,
        cues: Vec<RuntimeCue>,
        last_error: Option<String>,
    },
    RestoreExclusiveVideoTake {
        video_layers: Vec<RuntimeVideoLayer>,
        video_layer_fades: Vec<RuntimeVideoLayerFade>,
        last_error: Option<String>,
    },
    RestoreVideoLayersAndCompositions {
        video_layers: Vec<RuntimeVideoLayer>,
        video_compositions: Vec<RuntimeVideoComposition>,
        last_error: Option<String>,
    },
    RestoreVideoLayerIsfEffect {
        layer_id: VideoLayerId,
        effect: Option<VideoIsfEffectSummary>,
        last_error: Option<String>,
    },
    RestoreVideoLayerIsfEffectAndCancelEventPulse {
        layer_id: VideoLayerId,
        effect: Option<VideoIsfEffectSummary>,
        pulse_id: u64,
        replaced_resets: Vec<PendingVideoIsfEventReset>,
        last_error: Option<String>,
    },
    RestoreAutoVj {
        auto_vj: RuntimeAutoVj,
        last_error: Option<String>,
    },
    RestoreGroupColors {
        group_colors: BTreeMap<String, String>,
        last_error: Option<String>,
    },
    RestoreCueRemoval {
        cues: Vec<RuntimeCue>,
        cue_lists: Vec<CueListSummary>,
        cue_list_effect_activation_cues: HashMap<CueListId, CueId>,
        active_group_cue_ids: HashMap<String, CueId>,
        cue_release_values: HashMap<CueId, HashMap<(FixtureId, String), u16>>,
        timeline_events: Vec<RuntimeTimelineEvent>,
        active_cue_id: Option<CueId>,
        active_fade: Option<RuntimeFade>,
        pending_cues: VecDeque<PendingCueTrigger>,
        timeline_position_ms: u64,
        timeline_playhead_boundary_armed: bool,
        timeline_evaluated_boundary_position_ms: Option<u64>,
        timeline_jump_landed_event_id: Option<TimelineEventId>,
        last_error: Option<String>,
    },
    RestoreTimelineEvents {
        timeline_events: Vec<RuntimeTimelineEvent>,
        timeline_position_ms: u64,
        timeline_playhead_boundary_armed: bool,
        timeline_evaluated_boundary_position_ms: Option<u64>,
        timeline_jump_landed_event_id: Option<TimelineEventId>,
        last_error: Option<String>,
    },
    RestoreTimelineItems {
        timeline_events: Vec<RuntimeTimelineEvent>,
        timeline_automations: Vec<RuntimeTimelineAutomation>,
        timeline_video_automations: Vec<RuntimeTimelineVideoAutomation>,
        timeline_position_ms: u64,
        timeline_playhead_boundary_armed: bool,
        timeline_evaluated_boundary_position_ms: Option<u64>,
        timeline_jump_landed_event_id: Option<TimelineEventId>,
        last_error: Option<String>,
    },
    RestoreTimelineLayers {
        timeline_layers: Vec<TimelineLayerSummary>,
        timeline_events: Vec<RuntimeTimelineEvent>,
        timeline_audio: Option<AudioAnalysisSummary>,
        timeline_audio_clips: Vec<TimelineAudioClipSummary>,
        timeline_audio_clips_derived: bool,
        timeline_audio_duration_ms: u64,
        timeline_position_ms: u64,
        last_error: Option<String>,
    },
    RestoreTimelineAudioMaster {
        audio_offset_ms: i64,
        audio_muted: bool,
        timeline_audio_clips: Vec<TimelineAudioClipSummary>,
        timeline_audio_clips_derived: bool,
        timeline_audio_duration_ms: u64,
        timeline_position_ms: u64,
        last_error: Option<String>,
    },
}

impl PendingCommandRollback {
    fn restores_last_error(&self) -> bool {
        matches!(
            self,
            Self::RemoveAddedEffect { .. }
                | Self::RestoreEffect { .. }
                | Self::RestoreEffectEnabled { .. }
                | Self::RestoreNodeGraphs { .. }
                | Self::RestoreExclusiveVideoTake { .. }
                | Self::RestoreVideoLayersAndCompositions { .. }
                | Self::RestoreVideoLayerIsfEffect { .. }
                | Self::RestoreVideoLayerIsfEffectAndCancelEventPulse { .. }
                | Self::RestoreAutoVj { .. }
                | Self::RestoreCueRemoval { .. }
                | Self::RestoreTimelineEvents { .. }
                | Self::RestoreTimelineItems { .. }
                | Self::RestoreTimelineLayers { .. }
                | Self::RestoreTimelineAudioMaster { .. }
                | Self::RestoreTouchSurface { .. }
        )
    }
}

