// T17 live modifier dial ranges. Speed multiplies the effect rate, size
// scales modulation depth, phase shifts the traversal offset by a turn
// fraction. Out-of-range or non-finite values fall back to neutral.
const CUE_LIVE_MODIFIER_SPEED_MIN: f32 = 0.05;
const CUE_LIVE_MODIFIER_SPEED_MAX: f32 = 20.0;
const CUE_LIVE_MODIFIER_SIZE_MAX: f32 = 2.0;

fn sanitize_live_modifier_speed(speed: f32) -> f32 {
    if !speed.is_finite() || speed <= 0.0 {
        1.0
    } else {
        speed.clamp(CUE_LIVE_MODIFIER_SPEED_MIN, CUE_LIVE_MODIFIER_SPEED_MAX)
    }
}

fn sanitize_live_modifier_size(size: f32) -> f32 {
    if !size.is_finite() || size < 0.0 {
        1.0
    } else {
        size.min(CUE_LIVE_MODIFIER_SIZE_MAX)
    }
}

fn sanitize_live_modifier_phase(phase: f32) -> f32 {
    if !phase.is_finite() {
        0.0
    } else {
        phase.rem_euclid(1.0)
    }
}

fn sanitize_cue_live_modifier_settings(
    settings: Option<CueLiveModifierSettings>,
) -> Option<CueLiveModifierSettings> {
    let settings = settings?;
    Some(CueLiveModifierSettings {
        speed: sanitize_live_modifier_speed(settings.speed),
        size: sanitize_live_modifier_size(settings.size),
        phase: sanitize_live_modifier_phase(settings.phase),
        flash: settings.flash,
    })
}

fn live_modifier_scaled_period_ms(period_ms: u64, speed: f32) -> u64 {
    (((period_ms as f64) / f64::from(speed)).round() as u64).max(1)
}

fn live_modifier_scaled_clock_sync(
    clock_sync: Option<EffectClockSync>,
    speed: f32,
) -> Option<EffectClockSync> {
    clock_sync.map(|sync| EffectClockSync {
        beats: (sync.beats / speed).max(f32::MIN_POSITIVE),
    })
}

fn live_modifier_scaled_level_range(low: u16, high: u16, size: f32) -> (u16, u16) {
    let mid = (f32::from(low) + f32::from(high)) / 2.0;
    let half = (f32::from(high) - f32::from(low)) / 2.0 * size;
    (
        (mid - half).round().clamp(0.0, 65535.0) as u16,
        (mid + half).round().clamp(0.0, 65535.0) as u16,
    )
}

fn live_modifier_shifted_phase(phase: f32, offset: f32) -> f32 {
    (phase + offset).rem_euclid(1.0)
}

/// Applies one scene's effective live modifier to authored effect params.
/// Kind mapping: speed scales period/step duration/wave speed and shared-clock
/// beats; size scales level ranges (Lfo/PositionWave/Value/Curve/Mapping), Chaser feature
/// ranges, and Move path size; Color and Colour Mapping have no amplitude so
/// size is a deliberate no-op there; phase adds a wrapped traversal offset on
/// every kind.
fn effect_params_with_live_modifier(
    params: &EffectParamsSnapshot,
    modifier: CueLiveModifierSettings,
) -> EffectParamsSnapshot {
    let mut params = params.clone();
    match &mut params {
        EffectParamsSnapshot::Lfo(request) => {
            request.period_ms = live_modifier_scaled_period_ms(request.period_ms, modifier.speed);
            request.clock_sync =
                live_modifier_scaled_clock_sync(request.clock_sync, modifier.speed);
            let (low, high) =
                live_modifier_scaled_level_range(request.low, request.high, modifier.size);
            request.low = low;
            request.high = high;
            request.phase = live_modifier_shifted_phase(request.phase, modifier.phase);
        }
        EffectParamsSnapshot::PositionWave(request) => {
            request.speed *= modifier.speed;
            request.clock_sync =
                live_modifier_scaled_clock_sync(request.clock_sync, modifier.speed);
            let (low, high) =
                live_modifier_scaled_level_range(request.low, request.high, modifier.size);
            request.low = low;
            request.high = high;
            request.phase = live_modifier_shifted_phase(request.phase, modifier.phase);
        }
        EffectParamsSnapshot::Color(request) => {
            request.period_ms = live_modifier_scaled_period_ms(request.period_ms, modifier.speed);
            request.clock_sync =
                live_modifier_scaled_clock_sync(request.clock_sync, modifier.speed);
            request.phase = live_modifier_shifted_phase(request.phase, modifier.phase);
        }
        EffectParamsSnapshot::Chaser(request) => {
            request.step_duration_ms =
                live_modifier_scaled_period_ms(request.step_duration_ms, modifier.speed);
            request.clock_sync =
                live_modifier_scaled_clock_sync(request.clock_sync, modifier.speed);
            for feature in &mut request.features {
                let (low, high) =
                    live_modifier_scaled_level_range(feature.low, feature.high, modifier.size);
                feature.low = low;
                feature.high = high;
            }
            request.phase = live_modifier_shifted_phase(request.phase, modifier.phase);
        }
        EffectParamsSnapshot::Move(request) => {
            request.period_ms = live_modifier_scaled_period_ms(request.period_ms, modifier.speed);
            request.clock_sync =
                live_modifier_scaled_clock_sync(request.clock_sync, modifier.speed);
            request.size_x *= modifier.size;
            request.size_y *= modifier.size;
            request.phase = live_modifier_shifted_phase(request.phase, modifier.phase);
        }
        EffectParamsSnapshot::Value(request) => {
            request.period_ms = live_modifier_scaled_period_ms(request.period_ms, modifier.speed);
            request.clock_sync =
                live_modifier_scaled_clock_sync(request.clock_sync, modifier.speed);
            let (low, high) =
                live_modifier_scaled_level_range(request.low, request.high, modifier.size);
            request.low = low;
            request.high = high;
            request.phase = live_modifier_shifted_phase(request.phase, modifier.phase);
        }
        EffectParamsSnapshot::Curve(request) => {
            request.period_ms = live_modifier_scaled_period_ms(request.period_ms, modifier.speed);
            request.clock_sync =
                live_modifier_scaled_clock_sync(request.clock_sync, modifier.speed);
            let (low, high) =
                live_modifier_scaled_level_range(request.low, request.high, modifier.size);
            request.low = low;
            request.high = high;
            request.phase = live_modifier_shifted_phase(request.phase, modifier.phase);
        }
        EffectParamsSnapshot::Mapping(request) => {
            request.period_ms = live_modifier_scaled_period_ms(request.period_ms, modifier.speed);
            request.clock_sync =
                live_modifier_scaled_clock_sync(request.clock_sync, modifier.speed);
            let (low, high) =
                live_modifier_scaled_level_range(request.low, request.high, modifier.size);
            request.low = low;
            request.high = high;
            request.phase = live_modifier_shifted_phase(request.phase, modifier.phase);
        }
        EffectParamsSnapshot::ColorMapping(request) => {
            request.period_ms = live_modifier_scaled_period_ms(request.period_ms, modifier.speed);
            request.clock_sync =
                live_modifier_scaled_clock_sync(request.clock_sync, modifier.speed);
            request.phase = live_modifier_shifted_phase(request.phase, modifier.phase);
        }
    }
    params
}

fn normalize_cue_group_id(group_id: Option<String>) -> Option<String> {
    group_id.and_then(|group_id| {
        let group_id = group_id.trim().to_string();
        (!group_id.is_empty()).then_some(group_id)
    })
}

fn validate_and_sanitize_palette(
    mut palette: ReferencePaletteSummary,
) -> Result<ReferencePaletteSummary, String> {
    if palette.id == 0 {
        return Err("Palette ID must be greater than zero".to_string());
    }
    palette.label = palette.label.trim().chars().take(64).collect();
    if palette.label.is_empty() {
        return Err("Palette label is required".to_string());
    }
    if palette.values.is_empty() || palette.values.len() > 128 {
        return Err("A palette must contain from 1 to 128 attribute values".to_string());
    }
    let mut attributes = HashSet::new();
    for value in &mut palette.values {
        value.attribute = value.attribute.trim().chars().take(128).collect();
        if value.attribute.is_empty() || !attributes.insert(value.attribute.to_ascii_lowercase()) {
            return Err("Palette attributes must be non-empty and unique".to_string());
        }
    }
    Ok(palette)
}

fn sanitize_loaded_palettes(palettes: &[ReferencePaletteSummary]) -> Vec<ReferencePaletteSummary> {
    let mut ids = HashSet::new();
    let mut sanitized = palettes
        .iter()
        .take(128)
        .cloned()
        .filter_map(|palette| validate_and_sanitize_palette(palette).ok())
        .filter(|palette| ids.insert(palette.id))
        .collect::<Vec<_>>();
    sanitized.sort_by_key(|palette| palette.id);
    sanitized
}

fn validate_and_sanitize_cue_palette_targets(
    targets: Vec<CuePaletteTarget>,
    palettes: &[ReferencePaletteSummary],
    fixtures: &[RuntimeFixture],
) -> Result<Vec<CuePaletteTarget>, String> {
    if targets.len() > 128 {
        return Err("A cue can reference at most 128 palettes".to_string());
    }
    let palette_ids = palettes
        .iter()
        .map(|palette| palette.id)
        .collect::<HashSet<_>>();
    let fixture_ids = fixtures
        .iter()
        .map(|fixture| fixture.id)
        .collect::<HashSet<_>>();
    let mut seen_palettes = HashSet::new();
    let mut sanitized = Vec::with_capacity(targets.len());
    for mut target in targets {
        if !palette_ids.contains(&target.palette_id) {
            return Err(format!("Palette {} was not found", target.palette_id));
        }
        if !seen_palettes.insert(target.palette_id) {
            return Err(format!(
                "Palette {} can only be referenced once per cue",
                target.palette_id
            ));
        }
        target.fixture_ids.sort_unstable();
        target.fixture_ids.dedup();
        if target.fixture_ids.is_empty() {
            return Err(format!(
                "Palette {} must target at least one fixture",
                target.palette_id
            ));
        }
        if let Some(fixture_id) = target
            .fixture_ids
            .iter()
            .find(|fixture_id| !fixture_ids.contains(fixture_id))
        {
            return Err(format!("Fixture {fixture_id} was not found"));
        }
        sanitized.push(target);
    }
    sanitized.sort_by_key(|target| target.palette_id);
    Ok(sanitized)
}

fn sanitize_loaded_cue_palette_targets(
    targets: Vec<CuePaletteTarget>,
    palettes: &[ReferencePaletteSummary],
    fixtures: &[RuntimeFixture],
) -> Vec<CuePaletteTarget> {
    let palette_ids = palettes
        .iter()
        .map(|palette| palette.id)
        .collect::<HashSet<_>>();
    let fixture_ids = fixtures
        .iter()
        .map(|fixture| fixture.id)
        .collect::<HashSet<_>>();
    let mut seen_palettes = HashSet::new();
    let mut sanitized = Vec::new();
    for mut target in targets.into_iter().take(128) {
        if !palette_ids.contains(&target.palette_id) || !seen_palettes.insert(target.palette_id) {
            continue;
        }
        target
            .fixture_ids
            .retain(|fixture_id| fixture_ids.contains(fixture_id));
        target.fixture_ids.sort_unstable();
        target.fixture_ids.dedup();
        if !target.fixture_ids.is_empty() {
            sanitized.push(target);
        }
    }
    sanitized.sort_by_key(|target| target.palette_id);
    sanitized
}

fn cue_fixture_target_ids(
    targets: &[CueFixtureTarget],
    palette_targets: &[CuePaletteTarget],
) -> HashSet<FixtureId> {
    targets
        .iter()
        .map(|target| target.fixture_id)
        .chain(
            palette_targets
                .iter()
                .flat_map(|target| target.fixture_ids.iter().copied()),
        )
        .collect()
}

fn validate_and_sanitize_mib_fixture_ids(
    mut fixture_ids: Vec<FixtureId>,
    targets: &[CueFixtureTarget],
    palette_targets: &[CuePaletteTarget],
) -> Result<Vec<FixtureId>, String> {
    if fixture_ids.len() > 256 {
        return Err("A Cue MIB filter can contain at most 256 fixtures".to_string());
    }
    fixture_ids.sort_unstable();
    fixture_ids.dedup();
    let target_ids = cue_fixture_target_ids(targets, palette_targets);
    if let Some(fixture_id) = fixture_ids
        .iter()
        .find(|fixture_id| !target_ids.contains(fixture_id))
    {
        return Err(format!(
            "MIB fixture {fixture_id} is not targeted by this Cue"
        ));
    }
    Ok(fixture_ids)
}

fn reconcile_mib_fixture_ids(
    fixture_ids: Vec<FixtureId>,
    targets: &[CueFixtureTarget],
    palette_targets: &[CuePaletteTarget],
) -> Vec<FixtureId> {
    let target_ids = cue_fixture_target_ids(targets, palette_targets);
    let mut reconciled = fixture_ids
        .into_iter()
        .filter(|fixture_id| target_ids.contains(fixture_id))
        .collect::<Vec<_>>();
    reconciled.sort_unstable();
    reconciled.dedup();
    reconciled.truncate(256);
    reconciled
}

fn validate_and_sanitize_cue_parts(
    parts: Vec<CuePartSummary>,
    targets: &[CueFixtureTarget],
    video_targets: &[VideoLayerTarget],
    video_output_targets: &[VideoOutputTarget],
) -> Result<Vec<CuePartSummary>, String> {
    if parts.len() > 16 {
        return Err("A cue can contain at most 16 parts".to_string());
    }
    let target_ids = targets
        .iter()
        .map(|target| target.fixture_id)
        .collect::<HashSet<_>>();
    let video_layer_ids = video_targets
        .iter()
        .map(|target| target.layer_id)
        .collect::<HashSet<_>>();
    let video_output_ids = video_output_targets
        .iter()
        .map(|target| target.output_id)
        .collect::<HashSet<_>>();
    let mut numbers = HashSet::new();
    let mut assigned_fixture_ids = HashSet::new();
    let mut assigned_video_layer_ids = HashSet::new();
    let mut assigned_video_output_ids = HashSet::new();
    let mut sanitized = Vec::with_capacity(parts.len());
    for mut part in parts {
        if part.number == 0 || part.number > 999 || !numbers.insert(part.number) {
            return Err("Cue Part numbers must be unique values from 1 to 999".to_string());
        }
        part.label = part.label.trim().chars().take(64).collect();
        if part.label.is_empty() {
            return Err(format!("Cue Part {} label is required", part.number));
        }
        part.fixture_ids.sort_unstable();
        part.fixture_ids.dedup();
        for fixture_id in &part.fixture_ids {
            if !target_ids.contains(fixture_id) {
                return Err(format!(
                    "Cue Part {} references fixture {} outside this cue",
                    part.number, fixture_id
                ));
            }
            if !assigned_fixture_ids.insert(*fixture_id) {
                return Err(format!(
                    "Fixture {} is assigned to more than one Cue Part",
                    fixture_id
                ));
            }
        }
        part.video_layer_ids.sort_unstable();
        part.video_layer_ids.dedup();
        for layer_id in &part.video_layer_ids {
            if !video_layer_ids.contains(layer_id) {
                return Err(format!(
                    "Cue Part {} references video layer {} outside this cue",
                    part.number, layer_id
                ));
            }
            if !assigned_video_layer_ids.insert(*layer_id) {
                return Err(format!(
                    "Video layer {} is assigned to more than one Cue Part",
                    layer_id
                ));
            }
        }
        part.video_output_ids.sort_unstable();
        part.video_output_ids.dedup();
        for output_id in &part.video_output_ids {
            if !video_output_ids.contains(output_id) {
                return Err(format!(
                    "Cue Part {} references video output {} outside this cue",
                    part.number, output_id
                ));
            }
            if !assigned_video_output_ids.insert(*output_id) {
                return Err(format!(
                    "Video output {} is assigned to more than one Cue Part",
                    output_id
                ));
            }
        }
        sanitized.push(part);
    }
    sanitized.sort_by_key(|part| part.number);
    Ok(sanitized)
}

fn reconcile_cue_parts(
    parts: Vec<CuePartSummary>,
    targets: &[CueFixtureTarget],
    video_targets: &[VideoLayerTarget],
    video_output_targets: &[VideoOutputTarget],
) -> Vec<CuePartSummary> {
    let target_ids = targets
        .iter()
        .map(|target| target.fixture_id)
        .collect::<HashSet<_>>();
    let video_layer_ids = video_targets
        .iter()
        .map(|target| target.layer_id)
        .collect::<HashSet<_>>();
    let video_output_ids = video_output_targets
        .iter()
        .map(|target| target.output_id)
        .collect::<HashSet<_>>();
    let mut numbers = HashSet::new();
    let mut assigned_fixture_ids = HashSet::new();
    let mut assigned_video_layer_ids = HashSet::new();
    let mut assigned_video_output_ids = HashSet::new();
    let mut reconciled = parts
        .into_iter()
        .take(16)
        .filter_map(|mut part| {
            if part.number == 0 || part.number > 999 || !numbers.insert(part.number) {
                return None;
            }
            part.label = part.label.trim().chars().take(64).collect();
            if part.label.is_empty() {
                part.label = format!("Part {}", part.number);
            }
            part.fixture_ids.retain(|fixture_id| {
                target_ids.contains(fixture_id) && assigned_fixture_ids.insert(*fixture_id)
            });
            part.fixture_ids.sort_unstable();
            part.fixture_ids.dedup();
            part.video_layer_ids.retain(|layer_id| {
                video_layer_ids.contains(layer_id) && assigned_video_layer_ids.insert(*layer_id)
            });
            part.video_layer_ids.sort_unstable();
            part.video_layer_ids.dedup();
            part.video_output_ids.retain(|output_id| {
                video_output_ids.contains(output_id) && assigned_video_output_ids.insert(*output_id)
            });
            part.video_output_ids.sort_unstable();
            part.video_output_ids.dedup();
            Some(part)
        })
        .collect::<Vec<_>>();
    reconciled.sort_by_key(|part| part.number);
    reconciled
}

fn sanitize_cue_lists(cue_lists: &[CueListSummary], cues: &[RuntimeCue]) -> Vec<CueListSummary> {
    let mut sanitized = Vec::new();
    let mut seen = HashSet::new();
    for cue_list in cue_lists {
        if cue_list.id == 0 || !seen.insert(cue_list.id) {
            continue;
        }
        let label = cue_list.label.trim().chars().take(64).collect::<String>();
        sanitized.push(CueListSummary {
            id: cue_list.id,
            label: if label.is_empty() {
                format!("Cue List {}", cue_list.id)
            } else {
                label
            },
            active_cue_id: cue_list.active_cue_id.filter(|cue_id| {
                cues.iter()
                    .any(|cue| cue.id == *cue_id && cue.cue_list_id == cue_list.id)
            }),
        });
    }
    if !seen.contains(&DEFAULT_CUE_LIST_ID) {
        sanitized.insert(0, CueListSummary::default());
        seen.insert(DEFAULT_CUE_LIST_ID);
    }
    for cue in cues {
        if seen.insert(cue.cue_list_id) {
            sanitized.push(CueListSummary {
                id: cue.cue_list_id,
                label: format!("Cue List {}", cue.cue_list_id),
                active_cue_id: None,
            });
        }
    }
    sanitized.sort_by_key(|cue_list| (cue_list.id != DEFAULT_CUE_LIST_ID, cue_list.id));
    sanitized
}

fn validate_and_sanitize_playback_executor(
    mut executor: PlaybackExecutorSummary,
    cue_lists: &[CueListSummary],
    existing: &[PlaybackExecutorSummary],
) -> Result<PlaybackExecutorSummary, String> {
    if executor.id == 0 {
        return Err("Playback Executor ID must be greater than zero".to_string());
    }
    executor.label = executor.label.trim().chars().take(64).collect();
    if executor.label.is_empty() {
        return Err("Playback Executor label is required".to_string());
    }
    if !cue_lists
        .iter()
        .any(|cue_list| cue_list.id == executor.cue_list_id)
    {
        return Err(format!("Cue List {} was not found", executor.cue_list_id));
    }
    if executor.page == 0 || executor.page > 99 || executor.slot == 0 || executor.slot > 16 {
        return Err("Playback Executor page must be 1-99 and slot must be 1-16".to_string());
    }
    if !executor.level.is_finite() {
        return Err("Playback Executor level must be finite".to_string());
    }
    if existing.iter().any(|candidate| {
        candidate.id != executor.id
            && candidate.page == executor.page
            && candidate.slot == executor.slot
    }) {
        return Err(format!(
            "Playback Executor page {} slot {} is already in use",
            executor.page, executor.slot
        ));
    }
    executor.level = executor.level.clamp(0.0, 1.0);
    Ok(executor)
}

fn sanitize_playback_executors(
    executors: &[PlaybackExecutorSummary],
    cue_lists: &[CueListSummary],
) -> Vec<PlaybackExecutorSummary> {
    let mut sanitized = Vec::new();
    for executor in executors.iter().take(64).cloned() {
        if let Ok(executor) =
            validate_and_sanitize_playback_executor(executor, cue_lists, &sanitized)
        {
            sanitized.push(executor);
        }
    }
    if sanitized.is_empty() {
        sanitized.push(PlaybackExecutorSummary::default());
    }
    sanitized.sort_by_key(|executor| (executor.page, executor.slot, executor.id));
    sanitized
}

fn video_layer_summary(layer: &RuntimeVideoLayer) -> VideoLayerSummary {
    VideoLayerSummary {
        id: layer.id,
        label: layer.label.clone(),
        source: layer.source.clone(),
        blend_mode: layer.blend_mode.clone(),
        state: layer.state.clone(),
        isf_effect: layer.isf_effect.clone(),
    }
}

fn runtime_video_layer_from_summary(layer: &VideoLayerSummary) -> RuntimeVideoLayer {
    let mut isf_effect = layer.isf_effect.clone();
    if let Some(effect) = &mut isf_effect {
        clear_transient_video_isf_event_controls(effect);
    }
    RuntimeVideoLayer {
        id: layer.id,
        label: sanitize_video_layer_label(layer.label.clone(), layer.id),
        source: layer.source.clone(),
        blend_mode: layer.blend_mode.clone(),
        state: video::sanitize_layer_state(layer.state.clone()),
        isf_effect,
    }
}

const LEGACY_LIGHTING_TIMELINE_LAYER_ID: u32 = 0;
const LEGACY_VIDEO_TIMELINE_LAYER_ID: u32 = 1;
const LEGACY_AUDIO_TIMELINE_LAYER_ID: u32 = 2;

#[derive(Clone, Copy)]
struct ResolvedTimelineLayer {
    id: u32,
    order: u32,
    muted_effective: bool,
    locked: bool,
    kind: TimelineLayerKind,
}

fn implicit_timeline_layers() -> Vec<TimelineLayerSummary> {
    vec![
        TimelineLayerSummary {
            id: LEGACY_LIGHTING_TIMELINE_LAYER_ID,
            label: "Lighting".to_string(),
            order: 0,
            muted: false,
            locked: false,
            solo: false,
            kind: TimelineLayerKind::Lighting,
        },
        TimelineLayerSummary {
            id: LEGACY_VIDEO_TIMELINE_LAYER_ID,
            label: "Video".to_string(),
            order: 1,
            muted: false,
            locked: false,
            solo: false,
            kind: TimelineLayerKind::Video,
        },
    ]
}

fn default_timeline_audio_layer(id: u32) -> TimelineLayerSummary {
    TimelineLayerSummary {
        id,
        label: "Audio".to_string(),
        order: 0,
        muted: false,
        locked: false,
        solo: false,
        kind: TimelineLayerKind::Audio,
    }
}

fn first_timeline_audio_layer_id(layers: &[TimelineLayerSummary]) -> Option<u32> {
    layers
        .iter()
        .filter(|layer| matches!(layer.kind, TimelineLayerKind::Audio))
        .min_by_key(|layer| (layer.order, layer.id))
        .map(|layer| layer.id)
}

fn next_timeline_audio_layer_id(layers: &[TimelineLayerSummary]) -> u32 {
    layers
        .iter()
        .map(|layer| layer.id)
        .max()
        .unwrap_or(LEGACY_VIDEO_TIMELINE_LAYER_ID)
        .saturating_add(1)
        .max(LEGACY_AUDIO_TIMELINE_LAYER_ID)
}

fn legacy_timeline_audio_clip(
    audio: &AudioAnalysisSummary,
    layer_id: u32,
    audio_offset_ms: i64,
) -> TimelineAudioClipSummary {
    let (start_ms, offset_ms) = if audio_offset_ms >= 0 {
        (audio_offset_ms as u64, 0)
    } else {
        (0, audio_offset_ms.unsigned_abs())
    };
    TimelineAudioClipSummary {
        id: 0,
        layer_id,
        path: audio.path.clone(),
        start_ms,
        offset_ms,
        duration_ms: audio.duration_ms.saturating_sub(offset_ms),
        gain: 1.0,
        fade_in_ms: 0,
        fade_out_ms: 0,
    }
}

fn timeline_track_for_layer_kind(kind: TimelineLayerKind) -> Option<TimelineTrackKind> {
    match kind {
        TimelineLayerKind::Lighting => Some(TimelineTrackKind::Lighting),
        TimelineLayerKind::Video => Some(TimelineTrackKind::Video),
        TimelineLayerKind::Audio => None,
    }
}

fn sanitize_timeline_layer_label(layer: &mut TimelineLayerSummary) -> Result<(), String> {
    layer.label = layer.label.trim().to_string();
    if layer.label.is_empty() {
        return Err(format!(
            "Timeline layer {} label must not be empty",
            layer.id
        ));
    }
    Ok(())
}

fn normalize_timeline_layer_orders(layers: &mut Vec<TimelineLayerSummary>) -> Result<(), String> {
    let mut ids = HashSet::with_capacity(layers.len());
    for layer in layers.iter_mut() {
        sanitize_timeline_layer_label(layer)?;
        if !ids.insert(layer.id) {
            return Err(format!("Timeline layer {} is duplicated", layer.id));
        }
    }
    layers.sort_by_key(|layer| (layer.kind.display_section_rank(), layer.order, layer.id));
    for (index, layer) in layers.iter_mut().enumerate() {
        layer.order = u32::try_from(index).unwrap_or(u32::MAX);
    }
    Ok(())
}

fn effective_timeline_layer_by_id(
    layers: &[TimelineLayerSummary],
    layer_id: u32,
) -> Option<ResolvedTimelineLayer> {
    if layers.is_empty() {
        return match layer_id {
            LEGACY_LIGHTING_TIMELINE_LAYER_ID => Some(ResolvedTimelineLayer {
                id: LEGACY_LIGHTING_TIMELINE_LAYER_ID,
                order: 0,
                muted_effective: false,
                locked: false,
                kind: TimelineLayerKind::Lighting,
            }),
            LEGACY_VIDEO_TIMELINE_LAYER_ID => Some(ResolvedTimelineLayer {
                id: LEGACY_VIDEO_TIMELINE_LAYER_ID,
                order: 1,
                muted_effective: false,
                locked: false,
                kind: TimelineLayerKind::Video,
            }),
            _ => None,
        };
    }
    layers
        .iter()
        .find(|layer| layer.id == layer_id)
        .map(|layer| ResolvedTimelineLayer {
            id: layer.id,
            order: layer.order,
            muted_effective: layer.muted,
            locked: layer.locked,
            kind: layer.kind,
        })
}

fn resolve_timeline_layer(
    layers: &[TimelineLayerSummary],
    layer_id: Option<u32>,
    track: &TimelineTrackKind,
    any_solo: bool,
) -> Result<ResolvedTimelineLayer, String> {
    let mut resolved = if let Some(layer_id) = layer_id {
        effective_timeline_layer_by_id(layers, layer_id)
            .ok_or_else(|| format!("Timeline layer {layer_id} was not found"))?
    } else if layers.is_empty() {
        let implicit_id = match track {
            TimelineTrackKind::Lighting => LEGACY_LIGHTING_TIMELINE_LAYER_ID,
            TimelineTrackKind::Video => LEGACY_VIDEO_TIMELINE_LAYER_ID,
        };
        effective_timeline_layer_by_id(layers, implicit_id)
            .expect("implicit timeline layer must exist")
    } else {
        let kind = TimelineLayerKind::from(track);
        let layer = layers
            .iter()
            .find(|layer| layer.kind == kind)
            .ok_or_else(|| {
                format!(
                    "Legacy {:?} timeline event has no matching timeline layer",
                    track
                )
            })?;
        effective_timeline_layer_by_id(layers, layer.id)
            .expect("selected explicit timeline layer must exist")
    };
    if matches!(resolved.kind, TimelineLayerKind::Audio) {
        return Err(format!(
            "Cue events cannot be placed on Audio timeline layer {}",
            resolved.id
        ));
    }
    if !layers.is_empty() {
        let layer = layers
            .iter()
            .find(|layer| layer.id == resolved.id)
            .expect("resolved explicit timeline layer must exist");
        resolved.muted_effective = layer.muted || (any_solo && !layer.solo);
    }
    Ok(resolved)
}

fn resolve_timeline_event_layer(
    layers: &[TimelineLayerSummary],
    event: &RuntimeTimelineEvent,
    any_solo: bool,
) -> Result<ResolvedTimelineLayer, String> {
    resolve_timeline_layer(layers, event.layer_id, &event.track, any_solo)
}

fn normalize_and_validate_timeline_layers(
    layers: &mut Vec<TimelineLayerSummary>,
    events: &[TimelineCueEventSummary],
) -> Result<(), String> {
    normalize_timeline_layer_orders(layers)?;
    let any_solo = layers.iter().any(|layer| layer.solo);
    for event in events {
        resolve_timeline_layer(layers, event.layer_id, &event.track, any_solo).map_err(
            |error| format!("Timeline event {} has an invalid layer: {error}", event.id),
        )?;
    }
    Ok(())
}

fn normalize_and_validate_timeline_audio_clips(
    layers: &[TimelineLayerSummary],
    clips: &mut Vec<TimelineAudioClipSummary>,
) -> Result<(), String> {
    let mut ids = HashSet::with_capacity(clips.len());
    for clip in clips.iter_mut() {
        if !ids.insert(clip.id) {
            return Err(format!(
                "Timeline contains duplicate audio clip {}",
                clip.id
            ));
        }
        clip.path = clip.path.trim().to_string();
        if clip.path.is_empty() {
            return Err(format!(
                "Timeline audio clip {} path must not be empty",
                clip.id
            ));
        }
        if clip.duration_ms == 0 {
            return Err(format!(
                "Timeline audio clip {} duration must be greater than zero",
                clip.id
            ));
        }
        let layer = layers
            .iter()
            .find(|layer| layer.id == clip.layer_id)
            .ok_or_else(|| {
                format!(
                    "Timeline audio clip {} references missing layer {}",
                    clip.id, clip.layer_id
                )
            })?;
        if !matches!(layer.kind, TimelineLayerKind::Audio) {
            return Err(format!(
                "Timeline audio clip {} references non-Audio layer {}",
                clip.id, clip.layer_id
            ));
        }
        clip.start_ms = clip.start_ms.min(u64::MAX.saturating_sub(clip.duration_ms));
        clip.gain = if clip.gain.is_finite() {
            clip.gain.clamp(0.0, 2.0)
        } else {
            1.0
        };
        clip.fade_in_ms = clip.fade_in_ms.min(clip.duration_ms);
        clip.fade_out_ms = clip
            .fade_out_ms
            .min(clip.duration_ms.saturating_sub(clip.fade_in_ms));
    }
    clips.sort_by_key(|clip| (clip.start_ms, clip.layer_id, clip.id));
    Ok(())
}

fn validate_cue_authored_beats(authored_beats: Option<f32>) -> Result<Option<f32>, String> {
    match authored_beats {
        Some(beats)
            if !beats.is_finite()
                || !(MIN_CUE_AUTHORED_BEATS..=MAX_CUE_AUTHORED_BEATS).contains(&beats) =>
        {
            Err(format!(
                "Cue authored beats must be between {MIN_CUE_AUTHORED_BEATS} and {MAX_CUE_AUTHORED_BEATS}"
            ))
        }
        _ => Ok(authored_beats),
    }
}

fn rounded_timeline_milliseconds(value: f64, label: &str) -> Result<u64, String> {
    if !value.is_finite() || value <= 0.0 || value > u64::MAX as f64 {
        return Err(format!("{label} exceeds the supported timeline range"));
    }
    Ok(value.round().clamp(1.0, u64::MAX as f64) as u64)
}

fn timeline_conform_rate(free_run_period_ms: f64, conformed_period_ms: f64) -> Option<f32> {
    let rate = free_run_period_ms / conformed_period_ms;
    (rate.is_finite() && rate > 0.0 && rate <= f64::from(f32::MAX)).then_some(rate as f32)
}

fn runtime_effect_free_run_period_ms(kind: &RuntimeEffectKind) -> Option<f64> {
    let period_ms = match kind {
        RuntimeEffectKind::Lfo(request) => request.period_ms as f64,
        RuntimeEffectKind::PositionWave(request) => {
            let speed = f64::from(request.speed).abs();
            let wavelength = f64::from(request.wavelength).abs();
            if !speed.is_finite() || !wavelength.is_finite() || speed <= f64::EPSILON {
                return None;
            }
            wavelength / speed * 1_000.0
        }
        RuntimeEffectKind::Color(runtime) => runtime.request.period_ms as f64,
        RuntimeEffectKind::Chaser(runtime) => {
            runtime.request.step_duration_ms as f64 * runtime.step_order.len().max(1) as f64
        }
        RuntimeEffectKind::Move(runtime) => runtime.request.period_ms as f64,
        RuntimeEffectKind::Value(runtime) => runtime.request.period_ms as f64,
        RuntimeEffectKind::Curve(runtime) => runtime.request.period_ms as f64,
        RuntimeEffectKind::Mapping(runtime) => runtime.request.period_ms as f64,
        RuntimeEffectKind::ColorMapping(runtime) => runtime.request.period_ms as f64,
    };
    (period_ms.is_finite() && period_ms > 0.0).then_some(period_ms)
}

fn effect_params_snapshot_free_run_period_ms(params: &EffectParamsSnapshot) -> Option<f64> {
    let period_ms = match params {
        EffectParamsSnapshot::Lfo(request) => request.period_ms as f64,
        EffectParamsSnapshot::PositionWave(request) => {
            let speed = f64::from(request.speed).abs();
            let wavelength = f64::from(request.wavelength).abs();
            if !speed.is_finite() || !wavelength.is_finite() || speed <= f64::EPSILON {
                return None;
            }
            wavelength / speed * 1_000.0
        }
        EffectParamsSnapshot::Color(request) => request.period_ms as f64,
        EffectParamsSnapshot::Chaser(request) => {
            let path_len =
                chaser_step_order(request.direction, request.steps.len(), request.random_seed)
                    .len()
                    .max(1);
            request.step_duration_ms as f64 * path_len as f64
        }
        EffectParamsSnapshot::Move(request) => request.period_ms as f64,
        EffectParamsSnapshot::Value(request) => request.period_ms as f64,
        EffectParamsSnapshot::Curve(request) => request.period_ms as f64,
        EffectParamsSnapshot::Mapping(request) => request.period_ms as f64,
        EffectParamsSnapshot::ColorMapping(request) => request.period_ms as f64,
    };
    (period_ms.is_finite() && period_ms > 0.0).then_some(period_ms)
}

fn valid_effect_rate(rate: f32) -> f32 {
    if rate.is_finite() && rate > 0.0 {
        rate
    } else {
        1.0
    }
}

fn timeline_event_summary(event: &RuntimeTimelineEvent) -> TimelineCueEventSummary {
    TimelineCueEventSummary {
        id: event.id,
        cue_id: event.cue_id,
        time_ms: event.time_ms,
        time_beats: event.time_beats,
        track: event.track.clone(),
        layer_id: Some(event.resolved_layer_id),
        duration_ms: event.duration_ms,
        duration_beats: event.duration_beats,
        conform_to_tempo: event.conform_to_tempo,
        loop_fill: event.loop_fill,
        rate: event.rate,
        fade_in_ms: event.fade_in_ms,
        fade_out_ms: event.fade_out_ms,
        loop_count: event.loop_count,
        jump_to_event_id: event.jump_to_event_id,
    }
}

fn runtime_timeline_event_from_summary(event: &TimelineCueEventSummary) -> RuntimeTimelineEvent {
    let (loop_count, jump_to_event_id) = if event.duration_ms == 0 {
        (1, None)
    } else {
        (
            event.loop_count.clamp(1, MAX_TIMELINE_SCENE_BLOCK_LOOPS),
            event.jump_to_event_id,
        )
    };
    RuntimeTimelineEvent {
        id: event.id,
        cue_id: event.cue_id,
        time_ms: event.time_ms,
        time_beats: event.time_beats,
        track: event.track.clone(),
        layer_id: event.layer_id,
        resolved_layer_id: 0,
        layer_order: 0,
        layer_muted_effective: false,
        duration_ms: event.duration_ms,
        duration_beats: event.duration_beats,
        conform_to_tempo: event.conform_to_tempo,
        loop_fill: event.loop_fill,
        iteration_period_ms: event.duration_ms,
        // `rate` is derived runtime state. Never trust a persisted display value.
        rate: None,
        fade_in_ms: event.fade_in_ms.min(event.duration_ms),
        fade_out_ms: event.fade_out_ms.min(event.duration_ms),
        loop_count,
        jump_to_event_id,
    }
}

fn timeline_event_end_ms(event: &RuntimeTimelineEvent) -> u64 {
    let span_ms = if event.conform_to_tempo {
        event.duration_ms
    } else {
        event
            .duration_ms
            .saturating_mul(u64::from(event.loop_count))
    };
    event.time_ms.saturating_add(span_ms)
}

fn timeline_event_iteration_period_ms(event: &RuntimeTimelineEvent) -> u64 {
    if event.conform_to_tempo {
        event.iteration_period_ms
    } else {
        event.duration_ms
    }
}

fn child_transport_position_ms(transport: &RuntimeChildTransport, parent_position_ms: u64) -> u64 {
    let parent_delta_ms = parent_position_ms.saturating_sub(transport.window_start_ms);
    let scaled = ((parent_delta_ms as f64) * f64::from(transport.rate))
        .floor()
        .clamp(0.0, u64::MAX as f64) as u64;
    if transport.loop_fill && transport.duration_ms > 0 {
        scaled % transport.duration_ms
    } else {
        scaled.min(transport.duration_ms)
    }
}

fn child_timeline_audio_runtime_clips(
    snapshot: &EngineSnapshot,
) -> Vec<ChildTimelineAudioRuntimeClip> {
    if !snapshot.timeline.playing {
        return Vec::new();
    }
    let parent_position_ms = snapshot.timeline.position_ms;
    let mut active = Vec::new();
    let parent_any_solo = snapshot.timeline.layers.iter().any(|layer| layer.solo);
    for event in &snapshot.timeline.events {
        if event.duration_ms == 0 {
            continue;
        }
        if timeline_summary_event_is_muted(event, &snapshot.timeline.layers, parent_any_solo) {
            continue;
        }
        let end_ms = if event.conform_to_tempo {
            event.time_ms.saturating_add(event.duration_ms)
        } else {
            event.time_ms.saturating_add(
                event
                    .duration_ms
                    .saturating_mul(u64::from(event.loop_count.max(1))),
            )
        };
        if parent_position_ms < event.time_ms || parent_position_ms >= end_ms {
            continue;
        }
        let Some(cue) = snapshot.cues.iter().find(|cue| cue.id == event.cue_id) else {
            continue;
        };
        let Some(child) = cue.child_timeline.as_ref() else {
            continue;
        };
        if child_timeline_recall_is_inert(snapshot, cue.id, child) {
            continue;
        }
        let duration_ms = child
            .duration_ms
            .max(
                child
                    .events
                    .iter()
                    .map(|event| {
                        let span_ms = if event.conform_to_tempo {
                            event.duration_ms
                        } else {
                            event
                                .duration_ms
                                .saturating_mul(u64::from(event.loop_count.max(1)))
                        };
                        event.time_ms.saturating_add(span_ms)
                    })
                    .max()
                    .unwrap_or(0),
            )
            .max(
                child
                    .audio_clips
                    .iter()
                    .map(|clip| clip.start_ms.saturating_add(clip.duration_ms))
                    .max()
                    .unwrap_or(0),
            )
            .max(
                child
                    .audio
                    .as_ref()
                    .map(|audio| audio.duration_ms)
                    .unwrap_or(0),
            );
        if duration_ms == 0 {
            continue;
        }
        let parent_delta_ms = parent_position_ms.saturating_sub(event.time_ms);
        let rate = valid_effect_rate(event.rate.unwrap_or(1.0));
        let scaled_ms = ((parent_delta_ms as f64) * f64::from(rate))
            .floor()
            .clamp(0.0, u64::MAX as f64) as u64;
        let child_position_ms = if event.loop_fill {
            scaled_ms % duration_ms
        } else {
            scaled_ms.min(duration_ms)
        };
        let iteration_period_ms = if event.conform_to_tempo {
            cue.authored_beats
                .filter(|beats| beats.is_finite() && *beats > 0.0)
                .map(|beats| {
                    (f64::from(beats) * 60_000.0 / f64::from(clamp_bpm(snapshot.clock.bpm)))
                        .round()
                        .clamp(1.0, u64::MAX as f64) as u64
                })
                .unwrap_or(event.duration_ms.max(1))
        } else {
            event.duration_ms.max(1)
        };
        let parent_iteration = parent_delta_ms / iteration_period_ms;
        if child.audio_clips.is_empty() {
            if let Some(audio) = &child.audio {
                let layer_id = child
                    .layers
                    .iter()
                    .filter(|layer| matches!(layer.kind, TimelineLayerKind::Audio))
                    .min_by_key(|layer| (layer.order, layer.id))
                    .map(|layer| layer.id)
                    .unwrap_or(0);
                let clip = legacy_timeline_audio_clip(audio, layer_id, 0);
                if child_position_ms >= clip.start_ms
                    && child_position_ms < clip.start_ms.saturating_add(clip.duration_ms)
                {
                    active.push(ChildTimelineAudioRuntimeClip {
                        parent_event_id: event.id,
                        parent_iteration,
                        position_ms: child_position_ms,
                        clip,
                    });
                }
            }
            continue;
        }
        for clip in &child.audio_clips {
            if timeline_audio_clip_layer_is_muted(child, clip.layer_id) {
                continue;
            }
            if child_position_ms >= clip.start_ms
                && child_position_ms < clip.start_ms.saturating_add(clip.duration_ms)
            {
                active.push(ChildTimelineAudioRuntimeClip {
                    parent_event_id: event.id,
                    parent_iteration,
                    position_ms: child_position_ms,
                    clip: clip.clone(),
                });
            }
        }
    }
    active
}

fn timeline_summary_event_is_muted(
    event: &TimelineCueEventSummary,
    layers: &[TimelineLayerSummary],
    any_solo: bool,
) -> bool {
    if layers.is_empty() {
        return false;
    }
    let layer = event
        .layer_id
        .and_then(|layer_id| layers.iter().find(|layer| layer.id == layer_id))
        .or_else(|| {
            layers.iter().find(|layer| {
                timeline_track_for_layer_kind(layer.kind).as_ref() == Some(&event.track)
            })
        });
    layer.is_none_or(|layer| layer.muted || (any_solo && !layer.solo))
}

fn child_timeline_recall_is_inert(
    snapshot: &EngineSnapshot,
    owner_cue_id: CueId,
    child: &ChildTimelineSummary,
) -> bool {
    child.events.iter().any(|event| {
        event.cue_id == owner_cue_id
            || snapshot
                .cues
                .iter()
                .find(|cue| cue.id == event.cue_id)
                .is_none_or(|cue| cue.child_timeline.is_some())
    })
}

fn timeline_audio_clip_layer_is_muted(child: &ChildTimelineSummary, layer_id: u32) -> bool {
    let any_solo = child.layers.iter().any(|layer| layer.solo);
    child
        .layers
        .iter()
        .find(|layer| layer.id == layer_id && matches!(layer.kind, TimelineLayerKind::Audio))
        .is_none_or(|layer| layer.muted || (any_solo && !layer.solo))
}

fn timeline_block_iteration_range(
    event: &RuntimeTimelineEvent,
    lower_bound: u64,
    upper_bound: u64,
) -> Option<(u64, u64)> {
    let iteration_period_ms = timeline_event_iteration_period_ms(event);
    if event.duration_ms == 0 || iteration_period_ms == 0 || upper_bound < event.time_ms {
        return None;
    }
    let iteration_count = u64::from(event.loop_count);
    if iteration_count == 0 {
        return None;
    }
    let event_end_ms = timeline_event_end_ms(event);
    if lower_bound >= event_end_ms {
        return None;
    }
    let upper_bound = upper_bound.min(event_end_ms.saturating_sub(1));
    let first_iteration = if lower_bound <= event.time_ms {
        0
    } else {
        let delta = lower_bound - event.time_ms;
        1 + (delta - 1) / iteration_period_ms
    };
    let last_iteration = ((upper_bound - event.time_ms) / iteration_period_ms)
        .min(iteration_count.saturating_sub(1));
    (first_iteration < iteration_count && first_iteration <= last_iteration)
        .then_some((first_iteration, last_iteration))
}

fn try_collect_aligned_timeline_block_occurrences(
    events: &[RuntimeTimelineEvent],
    lower_bound: u64,
    upper_bound: u64,
    skip_landed_event_id: Option<TimelineEventId>,
    due: &mut Vec<TimelineCueOccurrence>,
) -> bool {
    // A large Scene Block stack commonly shares one start/duration/loop grid. Its event-major
    // occurrence streams are individually sorted but would otherwise require a large global sort.
    // When every due item uses the same grid and event ids are already ordered, emit the exact
    // `(time, event id)` order directly in O(occurrences). Any mixed/unsorted case falls back to
    // the general collector below.
    if skip_landed_event_id.is_some() {
        return false;
    }
    let mut grid = None;
    let mut relevant_event_count = 0_usize;
    let mut last_dispatch_key = None;
    for event in events {
        if event.duration_ms > 0
            && event.fade_out_ms > 0
            && (lower_bound..=upper_bound)
                .contains(&timeline_event_end_ms(event).saturating_sub(event.fade_out_ms))
        {
            return false;
        }
        if event.duration_ms > 0
            && (lower_bound..=upper_bound).contains(&timeline_event_end_ms(event))
        {
            return false;
        }
        if event.layer_muted_effective {
            continue;
        }
        if event.duration_ms == 0 {
            if (lower_bound..=upper_bound).contains(&event.time_ms) {
                return false;
            }
            continue;
        }
        let Some((first_iteration, last_iteration)) =
            timeline_block_iteration_range(event, lower_bound, upper_bound)
        else {
            continue;
        };
        let event_grid = (
            event.time_ms,
            timeline_event_iteration_period_ms(event),
            first_iteration,
            last_iteration,
        );
        let dispatch_key = (std::cmp::Reverse(event.layer_order), event.id);
        if grid.is_some_and(|grid| grid != event_grid)
            || last_dispatch_key.is_some_and(|last_key| dispatch_key <= last_key)
        {
            return false;
        }
        grid = Some(event_grid);
        last_dispatch_key = Some(dispatch_key);
        relevant_event_count += 1;
    }
    let Some((time_ms, iteration_period_ms, first_iteration, last_iteration)) = grid else {
        return false;
    };
    if relevant_event_count < 2 {
        return false;
    }

    for iteration in first_iteration..=last_iteration {
        let occurrence_ms = time_ms + iteration * iteration_period_ms;
        for (event_index, event) in events.iter().enumerate() {
            if !event.layer_muted_effective
                && event.time_ms == time_ms
                && timeline_event_iteration_period_ms(event) == iteration_period_ms
                && timeline_block_iteration_range(event, lower_bound, upper_bound)
                    == Some((first_iteration, last_iteration))
            {
                due.push(TimelineCueOccurrence {
                    time_ms: occurrence_ms,
                    event_index,
                    event_id: event.id,
                    cue_id: event.cue_id,
                    layer_order: event.layer_order,
                    iteration,
                    kind: TimelineCueOccurrenceKind::Trigger,
                });
            }
        }
    }
    true
}

fn collect_timeline_cue_occurrences_between(
    events: &[RuntimeTimelineEvent],
    previous_position: u64,
    current_position: u64,
    include_previous: bool,
    include_current: bool,
    skip_landed_event_id: Option<TimelineEventId>,
    due: &mut Vec<TimelineCueOccurrence>,
) {
    due.clear();
    if current_position < previous_position {
        return;
    }
    let lower_bound = if include_previous {
        previous_position
    } else if let Some(next) = previous_position.checked_add(1) {
        next
    } else {
        return;
    };
    let upper_bound = if include_current {
        current_position
    } else if let Some(previous) = current_position.checked_sub(1) {
        previous
    } else {
        return;
    };
    if lower_bound > upper_bound {
        return;
    }

    if try_collect_aligned_timeline_block_occurrences(
        events,
        lower_bound,
        upper_bound,
        skip_landed_event_id,
        due,
    ) {
        return;
    }

    for (event_index, event) in events.iter().enumerate() {
        if event.duration_ms > 0 {
            let end_ms = timeline_event_end_ms(event);
            let fade_out_start_ms = end_ms.saturating_sub(event.fade_out_ms);
            if (lower_bound..=upper_bound).contains(&end_ms) {
                due.push(TimelineCueOccurrence {
                    time_ms: end_ms,
                    event_index,
                    event_id: event.id,
                    cue_id: event.cue_id,
                    layer_order: event.layer_order,
                    iteration: u64::from(event.loop_count),
                    kind: TimelineCueOccurrenceKind::End,
                });
            }
            if event.fade_out_ms > 0
                && !event.layer_muted_effective
                && (lower_bound..=upper_bound).contains(&fade_out_start_ms)
            {
                due.push(TimelineCueOccurrence {
                    time_ms: fade_out_start_ms,
                    event_index,
                    event_id: event.id,
                    cue_id: event.cue_id,
                    layer_order: event.layer_order,
                    iteration: u64::from(event.loop_count),
                    kind: TimelineCueOccurrenceKind::FadeOutStart,
                });
            }
        }
        if event.layer_muted_effective {
            continue;
        }
        if event.duration_ms == 0 {
            let occurrence_ms = event.time_ms;
            let skipped_landing =
                skip_landed_event_id == Some(event.id) && occurrence_ms == previous_position;
            if occurrence_ms >= lower_bound && occurrence_ms <= upper_bound && !skipped_landing {
                due.push(TimelineCueOccurrence {
                    time_ms: occurrence_ms,
                    event_index,
                    event_id: event.id,
                    cue_id: event.cue_id,
                    layer_order: event.layer_order,
                    iteration: 0,
                    kind: TimelineCueOccurrenceKind::Trigger,
                });
            }
            continue;
        }

        let Some((mut first_iteration, last_iteration)) =
            timeline_block_iteration_range(event, lower_bound, upper_bound)
        else {
            continue;
        };
        if skip_landed_event_id == Some(event.id)
            && event.time_ms + first_iteration * timeline_event_iteration_period_ms(event)
                == previous_position
        {
            first_iteration = first_iteration.saturating_add(1);
        }
        if first_iteration > last_iteration {
            continue;
        }
        for iteration in first_iteration..=last_iteration {
            let occurrence_ms =
                event.time_ms + iteration * timeline_event_iteration_period_ms(event);
            let fade_out_start_ms = timeline_event_end_ms(event).saturating_sub(event.fade_out_ms);
            if iteration > 0 && event.fade_out_ms > 0 && occurrence_ms >= fade_out_start_ms {
                continue;
            }
            due.push(TimelineCueOccurrence {
                time_ms: occurrence_ms,
                event_index,
                event_id: event.id,
                cue_id: event.cue_id,
                layer_order: event.layer_order,
                iteration,
                kind: TimelineCueOccurrenceKind::Trigger,
            });
        }
    }
    due.sort_unstable_by(|left, right| {
        left.time_ms
            .cmp(&right.time_ms)
            .then_with(|| left.kind.cmp(&right.kind))
            .then_with(|| right.layer_order.cmp(&left.layer_order))
            .then_with(|| left.event_id.cmp(&right.event_id))
    });
}

