fn runtime_effect_from_summary(effect: &EffectSummary, now: Instant) -> Option<RuntimeEffect> {
    let kind = match effect.effect_type {
        EffectKind::Lfo => RuntimeEffectKind::Lfo(LfoEffectRequest {
            label: effect.label.clone(),
            fixture_ids: effect.fixture_ids.clone(),
            target_group_ids: effect.target_group_ids.clone(),
            attribute: effect.attribute.clone(),
            video_targets: effect.video_targets.clone(),
            shape: effect.shape.clone(),
            period_ms: effect.period_ms?,
            clock_sync: effect.clock_sync,
            low: effect.low,
            high: effect.high,
            phase: effect.phase,
            blend_mode: effect.blend_mode.clone(),
        }),
        EffectKind::PositionWave => RuntimeEffectKind::PositionWave(PositionWaveEffectRequest {
            label: effect.label.clone(),
            fixture_ids: effect.fixture_ids.clone(),
            target_group_ids: effect.target_group_ids.clone(),
            attribute: effect.attribute.clone(),
            video_targets: effect.video_targets.clone(),
            shape: effect.shape.clone(),
            origin: effect.origin?,
            direction: effect.direction?,
            speed: effect.speed?,
            wavelength: effect.wavelength?,
            clock_sync: effect.clock_sync,
            low: effect.low,
            high: effect.high,
            phase: effect.phase,
            blend_mode: effect.blend_mode.clone(),
        }),
        EffectKind::Color => RuntimeEffectKind::Color(RuntimeColorEffect {
            request: effect.color.clone()?,
            targets: Vec::new(),
            target_indices: HashMap::new(),
            spatial: None,
        }),
        EffectKind::Chaser => RuntimeEffectKind::Chaser(RuntimeChaserEffect {
            request: effect.chaser.clone()?,
            step_order: Vec::new(),
            target_phase_offsets: HashMap::new(),
            target_step_levels: HashMap::new(),
            target_level_cache: HashMap::new(),
            feature_indices: HashMap::new(),
            feature_fixture_ids: Vec::new(),
        }),
        EffectKind::Move => {
            let request = effect.move_effect.clone()?;
            let path = CompiledMovePath::compile(&request).ok()?;
            let (rotation_cosine, rotation_sine) = move_rotation(request.rotation_degrees);
            RuntimeEffectKind::Move(RuntimeMoveEffect {
                request,
                path,
                targets: Vec::new(),
                target_indices: HashMap::new(),
                rotation_cosine,
                rotation_sine,
            })
        }
        EffectKind::Value => {
            let request = effect.value.clone()?;
            let envelope = CompiledValueEnvelope::compile(&request);
            RuntimeEffectKind::Value(RuntimeValueEffect {
                request,
                envelope,
                targets: Vec::new(),
                target_indices: HashMap::new(),
            })
        }
        EffectKind::Curve => {
            let request = effect.curve.clone()?;
            let function = CompiledCurveFunction::compile(&request);
            RuntimeEffectKind::Curve(RuntimeCurveEffect {
                request,
                function,
                targets: Vec::new(),
                target_indices: HashMap::new(),
            })
        }
        EffectKind::Mapping => {
            let request = effect.mapping.clone()?;
            RuntimeEffectKind::Mapping(RuntimeMappingEffect {
                request,
                targets: Vec::new(),
                target_indices: HashMap::new(),
            })
        }
        EffectKind::ColorMapping => RuntimeEffectKind::ColorMapping(RuntimeColorMappingEffect {
            request: effect.color_mapping.clone()?,
            frames: Vec::new(),
            targets: Vec::new(),
            attribute_indices: HashMap::new(),
        }),
    };
    Some(RuntimeEffect {
        id: effect.id,
        kind,
        enabled: effect.enabled,
        created_at: now,
    })
}

fn validate_runtime_color_effect_request(request: &ColorEffectRequest) -> Result<(), String> {
    if request.label.trim().is_empty() {
        return Err("Color effect label is required".to_string());
    }
    if request.fixture_ids.is_empty() && request.target_group_ids.is_empty() {
        return Err("Color effect must target at least one fixture or group".to_string());
    }
    if !(2..=8).contains(&request.stops.len()) {
        return Err("Color effect requires between 2 and 8 stops".to_string());
    }
    let mut previous = None;
    for stop in &request.stops {
        if !stop.position.is_finite() || !(0.0..=1.0).contains(&stop.position) {
            return Err("Color effect stop positions must be finite and within 0..1".to_string());
        }
        if previous.is_some_and(|previous| stop.position <= previous) {
            return Err("Color effect stop positions must be strictly increasing".to_string());
        }
        previous = Some(stop.position);
    }
    if request.period_ms < 10 {
        return Err("Color effect period must be at least 10 ms".to_string());
    }
    if let Some(clock_sync) = request.clock_sync {
        if !clock_sync.beats.is_finite() || clock_sync.beats <= 0.0 {
            return Err(
                "Color effect clock sync beats must be finite and greater than 0".to_string(),
            );
        }
    }
    if !request.phase.is_finite() || !request.fixture_spread.is_finite() {
        return Err("Color effect phase and fixture spread must be finite".to_string());
    }
    if !(0.0..=1.0).contains(&request.fixture_spread) {
        return Err("Color effect fixture spread must be within 0..1".to_string());
    }
    if let Some(pattern) = &request.spatial_pattern {
        validate_color_spatial_recipe(&pattern.recipe)?;
        let mut beam_targets = HashSet::new();
        for target in &pattern.beam_targets {
            if !request.fixture_ids.contains(&target.fixture_id) {
                return Err(format!(
                    "Color beam target fixture {} is not present in fixture_ids",
                    target.fixture_id
                ));
            }
            if !beam_targets.insert((target.fixture_id, target.beam_index)) {
                return Err(format!(
                    "Color beam target fixture {} beam {} is duplicated",
                    target.fixture_id, target.beam_index
                ));
            }
        }
    }
    Ok(())
}

pub fn validate_color_effect_request(request: &ColorEffectRequest) -> Result<(), String> {
    validate_runtime_color_effect_request(request)
}

fn validate_color_spatial_recipe(recipe: &ColorEffectSpatialRecipe) -> Result<(), String> {
    let percent = |label: &str, value: f32| {
        if value.is_finite() && (0.0..=100.0).contains(&value) {
            Ok(())
        } else {
            Err(format!(
                "Color spatial {label} must be finite and within 0..100"
            ))
        }
    };
    match recipe {
        ColorEffectSpatialRecipe::KnightRider { size, gradient, .. } => {
            if *size == 0 {
                return Err("Knight Rider size must be at least 1".to_string());
            }
            percent("gradient", *gradient)
        }
        ColorEffectSpatialRecipe::Burst {
            color_width,
            gradient,
        } => {
            percent("color width", *color_width)?;
            percent("gradient", *gradient)
        }
        ColorEffectSpatialRecipe::RandomFill { point_width } => {
            if *point_width == 0 {
                Err("Random fill point width must be at least 1".to_string())
            } else {
                Ok(())
            }
        }
        ColorEffectSpatialRecipe::Sparkle {
            number,
            lifespan,
            width,
        } => {
            if *number == 0 || *width == 0 {
                return Err("Sparkle number and width must be at least 1".to_string());
            }
            percent("lifespan", *lifespan)
        }
        ColorEffectSpatialRecipe::Rainbow {
            rotation_degrees,
            color_width,
            angle_degrees,
            gradient,
            ..
        } => {
            if !rotation_degrees.is_finite() || !angle_degrees.is_finite() {
                return Err("Rainbow rotation and angle must be finite".to_string());
            }
            percent("color width", *color_width)?;
            percent("gradient", *gradient)
        }
        ColorEffectSpatialRecipe::Perlin {
            octaves,
            zoom,
            direction_degrees,
            speed,
            amplitude,
        } => {
            if !(1..=16).contains(octaves) {
                return Err("Perlin octaves must be within 1..16".to_string());
            }
            if !zoom.is_finite() || *zoom <= 0.0 {
                return Err("Perlin zoom must be finite and greater than 0".to_string());
            }
            if !direction_degrees.is_finite() || !speed.is_finite() {
                return Err("Perlin direction and speed must be finite".to_string());
            }
            percent("amplitude", *amplitude)
        }
    }
}

pub fn validate_move_effect_request(request: &MoveEffectRequest) -> Result<(), String> {
    if request.label.trim().is_empty() {
        return Err("Move effect label is required".to_string());
    }
    if request.fixture_ids.is_empty() && request.target_group_ids.is_empty() {
        return Err("Move effect must target at least one fixture or group".to_string());
    }
    if !(2..=256).contains(&request.points.len()) {
        return Err("Move effect requires between 2 and 256 path points".to_string());
    }
    if request.points.iter().any(|point| {
        !point.x.is_finite()
            || !point.y.is_finite()
            || !(0.0..=1.0).contains(&point.x)
            || !(0.0..=1.0).contains(&point.y)
    }) {
        return Err("Move effect path points must be finite and within 0..1".to_string());
    }
    let first_point = request.points[0];
    if !request
        .points
        .iter()
        .skip(1)
        .any(|point| (point.x - first_point.x).hypot(point.y - first_point.y) > 1.0e-6)
    {
        return Err("Move effect path must contain at least two distinct points".to_string());
    }
    if !request.center_x.is_finite()
        || !request.center_y.is_finite()
        || !(0.0..=1.0).contains(&request.center_x)
        || !(0.0..=1.0).contains(&request.center_y)
    {
        return Err("Move effect center must be finite and within 0..1".to_string());
    }
    if !request.size_x.is_finite()
        || !request.size_y.is_finite()
        || !(0.0..=2.0).contains(&request.size_x)
        || !(0.0..=2.0).contains(&request.size_y)
        || request.size_x == 0.0
        || request.size_y == 0.0
    {
        return Err("Move effect size must be finite, greater than 0, and at most 2".to_string());
    }
    if !request.rotation_degrees.is_finite() {
        return Err("Move effect rotation must be finite".to_string());
    }
    if request.period_ms < 10 {
        return Err("Move effect period must be at least 10 ms".to_string());
    }
    if let Some(clock_sync) = request.clock_sync {
        if !clock_sync.beats.is_finite() || clock_sync.beats <= 0.0 {
            return Err(
                "Move effect clock sync beats must be finite and greater than 0".to_string(),
            );
        }
    }
    if !request.phase.is_finite() || !(0.0..=1.0).contains(&request.phase) {
        return Err("Move effect phase must be finite and within 0..1".to_string());
    }
    if !request.fixture_spread.is_finite() || !(0.0..=1.0).contains(&request.fixture_spread) {
        return Err("Move effect fixture spread must be finite and within 0..1".to_string());
    }
    if request.blend_mode != EffectBlendMode::Override {
        return Err(
            "Move effects use Override semantics; Relative mode applies a signed offset"
                .to_string(),
        );
    }
    Ok(())
}

fn runtime_move_effect_from_request(
    request: MoveEffectRequest,
    fixtures: &[RuntimeFixture],
    require_resolved_target: bool,
) -> Result<RuntimeMoveEffect, String> {
    validate_move_effect_request(&request)?;
    let path = CompiledMovePath::compile(&request)?;
    let mut fixture_ids = Vec::new();
    let mut seen = HashSet::new();
    for fixture_id in &request.fixture_ids {
        if fixtures.iter().any(|fixture| fixture.id == *fixture_id) && seen.insert(*fixture_id) {
            fixture_ids.push(*fixture_id);
        }
    }
    for group_id in &request.target_group_ids {
        for fixture in fixtures.iter().filter(|fixture| {
            fixture
                .request
                .group_ids
                .iter()
                .any(|fixture_group| group_matches(fixture_group, group_id))
        }) {
            if seen.insert(fixture.id) {
                fixture_ids.push(fixture.id);
            }
        }
    }

    let compatible = fixture_ids
        .into_iter()
        .filter_map(|fixture_id| {
            let fixture = fixtures.iter().find(|fixture| fixture.id == fixture_id)?;
            let (pan_attribute, tilt_attribute) = runtime_move_attribute_pair(fixture)?;
            Some((
                fixture_id,
                pan_attribute.to_string(),
                tilt_attribute.to_string(),
            ))
        })
        .collect::<Vec<_>>();
    if require_resolved_target && compatible.is_empty() {
        return Err(
            "Move effect must resolve at least one fixture with one paired Pan and Tilt control"
                .to_string(),
        );
    }

    let count = compatible.len().max(1) as f32;
    let targets = compatible
        .into_iter()
        .enumerate()
        .map(
            |(index, (fixture_id, pan_attribute, tilt_attribute))| RuntimeMoveTarget {
                fixture_id,
                pan_attribute,
                tilt_attribute,
                phase_offset: index as f32 / count * request.fixture_spread,
                cached: Cell::new(None),
            },
        )
        .collect::<Vec<_>>();
    let target_indices = targets
        .iter()
        .enumerate()
        .map(|(index, target)| (target.fixture_id, index))
        .collect();
    let (rotation_cosine, rotation_sine) = move_rotation(request.rotation_degrees);
    Ok(RuntimeMoveEffect {
        request,
        path,
        targets,
        target_indices,
        rotation_cosine,
        rotation_sine,
    })
}

