#[allow(clippy::too_many_arguments)]
fn evaluate_color_effect_at_rate(
    request: &ColorEffectRequest,
    fixture_phase: f32,
    effect_id: EffectId,
    fixture_id: FixtureId,
    created_at: Instant,
    now: Instant,
    clock: &ClockSnapshot,
    rate: f32,
) -> ColorEffectColor {
    let rate = f64::from(valid_effect_rate(rate));
    let time_phase = request
        .clock_sync
        .map(|clock_sync| {
            (clock.beat_counter as f64 + clock.beat_phase as f64)
                / clock_sync.beats.max(0.000_1) as f64
                * rate
        })
        .unwrap_or_else(|| {
            now.saturating_duration_since(created_at).as_secs_f64() * rate
                / (request.period_ms.max(10) as f64 / 1000.0)
        });
    let absolute_phase = time_phase + request.phase as f64 + fixture_phase as f64;
    match request.algorithm {
        ColorEffectAlgorithm::Cycle => {
            evaluate_cycle_color(request, absolute_phase.rem_euclid(1.0) as f32)
        }
        ColorEffectAlgorithm::Bounce => {
            let phase = absolute_phase.rem_euclid(1.0) as f32;
            let position = if phase <= 0.5 {
                phase * 2.0
            } else {
                (1.0 - phase) * 2.0
            };
            evaluate_linear_stop_color(request, position)
        }
        ColorEffectAlgorithm::Sequence => {
            let phase = absolute_phase.rem_euclid(1.0) as f32;
            request
                .stops
                .iter()
                .rev()
                .find(|stop| stop.position <= phase)
                .unwrap_or_else(|| &request.stops[request.stops.len() - 1])
                .color
        }
        ColorEffectAlgorithm::Random => {
            let step = (absolute_phase * request.stops.len() as f64).floor() as i64;
            let random =
                splitmix64(effect_id ^ fixture_id.rotate_left(21) ^ (step as u64).rotate_left(43));
            request.stops[random as usize % request.stops.len()].color
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn evaluate_color_spatial_effect_at_rate(
    request: &ColorEffectRequest,
    target: &RuntimeColorSpatialTarget,
    effect_id: EffectId,
    created_at: Instant,
    now: Instant,
    clock: &ClockSnapshot,
    rate: f32,
) -> ColorEffectColor {
    let Some(pattern) = request.spatial_pattern.as_ref() else {
        return evaluate_color_effect_at_rate(
            request,
            0.0,
            effect_id,
            target.fixture_id,
            created_at,
            now,
            clock,
            rate,
        );
    };
    let rate = f64::from(valid_effect_rate(rate));
    let time_phase = request
        .clock_sync
        .map(|clock_sync| {
            (clock.beat_counter as f64 + clock.beat_phase as f64)
                / clock_sync.beats.max(0.000_1) as f64
                * rate
        })
        .unwrap_or_else(|| {
            now.saturating_duration_since(created_at).as_secs_f64() * rate
                / (request.period_ms.max(10) as f64 / 1000.0)
        })
        + request.phase as f64;
    let strip_count = target.strip_count.max(1);
    let strip_position = if strip_count <= 1 {
        0.5
    } else {
        target.strip_index as f32 / (strip_count - 1) as f32
    };
    let seed = effect_id
        ^ target.fixture_id.rotate_left(17)
        ^ u64::from(target.beam_index).rotate_left(41);

    match &pattern.recipe {
        ColorEffectSpatialRecipe::KnightRider {
            size,
            one_way,
            fading,
            go_outside,
            gradient,
        } => {
            let width =
                (f32::from(*size) / strip_count as f32).clamp(1.0 / strip_count as f32, 1.0);
            let half_width = width * 0.5;
            let phase = time_phase.rem_euclid(1.0) as f32;
            let travel = if *one_way {
                phase
            } else if phase <= 0.5 {
                phase * 2.0
            } else {
                (1.0 - phase) * 2.0
            };
            let center = if *go_outside {
                -half_width + travel * (1.0 + width)
            } else {
                travel
            };
            let mut distance = (strip_position - center).abs();
            if *one_way && !*go_outside {
                distance = distance.min(1.0 - distance);
            }
            if distance > half_width {
                return black_color();
            }
            let level = 1.0 - distance / half_width.max(f32::EPSILON);
            let color = spatial_palette_color(request, level, *gradient);
            if *fading {
                scale_color(color, level)
            } else {
                color
            }
        }
        ColorEffectSpatialRecipe::Burst {
            color_width,
            gradient,
        } => {
            let radius = (strip_position - 0.5).abs() * 2.0;
            let front = time_phase.rem_euclid(1.0) as f32;
            let width = (*color_width / 100.0).max(1.0 / strip_count as f32);
            let distance = (radius - front).abs();
            if distance > width {
                black_color()
            } else {
                spatial_palette_color(request, 1.0 - distance / width, *gradient)
            }
        }
        ColorEffectSpatialRecipe::RandomFill { point_width } => {
            let point_width = usize::from(*point_width).max(1);
            let cell_count = strip_count.div_ceil(point_width).max(1);
            let cell = target.strip_index / point_width;
            let phase = time_phase.rem_euclid(1.0) as f32;
            let filled = ((phase * cell_count as f32).floor() as usize + 1).min(cell_count);
            let rank = spatial_random_rank(cell, cell_count, effect_id);
            if rank >= filled {
                black_color()
            } else {
                let palette_index =
                    splitmix64(effect_id ^ cell as u64) as usize % request.stops.len();
                request.stops[palette_index].color
            }
        }
        ColorEffectSpatialRecipe::Sparkle {
            number,
            lifespan,
            width,
        } => {
            let epoch = time_phase.floor() as i64;
            let age = time_phase.rem_euclid(1.0) as f32;
            let life = (*lifespan / 100.0).max(0.04);
            if age > life {
                return black_color();
            }
            let radius = usize::from(*width).saturating_sub(1);
            for sparkle in 0..usize::from(*number) {
                let sparkle_seed =
                    seed ^ (epoch as u64).rotate_left(29) ^ (sparkle as u64).rotate_left(47);
                let center = splitmix64(sparkle_seed) as usize % strip_count;
                if target.strip_index.abs_diff(center) <= radius {
                    let palette_index =
                        splitmix64(sparkle_seed ^ 0xA53C_9E17) as usize % request.stops.len();
                    return scale_color(request.stops[palette_index].color, 1.0 - age / life);
                }
            }
            black_color()
        }
        ColorEffectSpatialRecipe::Rainbow {
            vertical_symmetry,
            rotation_degrees,
            color_width,
            angle_degrees,
            gradient,
        } => {
            let x = if *vertical_symmetry {
                (target.x * 2.0 - 1.0).abs()
            } else {
                target.x
            } - 0.5;
            let z = target.z - 0.5;
            let angle = (*rotation_degrees + *angle_degrees).to_radians();
            let projected = x * angle.cos() + z * angle.sin();
            let width_scale = 1.0 + *color_width / 100.0 * 7.0;
            let position = (projected * width_scale + time_phase as f32).rem_euclid(1.0);
            spatial_palette_color(request, position, *gradient)
        }
        ColorEffectSpatialRecipe::Perlin {
            octaves,
            zoom,
            direction_degrees,
            speed,
            amplitude,
        } => {
            let direction = direction_degrees.to_radians();
            let travel = time_phase as f32 * *speed;
            let scale = (*zoom / 10.0).max(0.001);
            let x = target.x * scale + travel * direction.cos();
            let z = target.z * scale + travel * direction.sin();
            let noise = spatial_fractal_noise(x, z, *octaves, effect_id as u32);
            let value = (0.5 + (noise - 0.5) * (*amplitude / 100.0)).clamp(0.0, 1.0);
            spatial_palette_color(request, value, 100.0)
        }
    }
}

fn black_color() -> ColorEffectColor {
    ColorEffectColor {
        red: 0,
        green: 0,
        blue: 0,
    }
}

fn scale_color(color: ColorEffectColor, amount: f32) -> ColorEffectColor {
    let amount = amount.clamp(0.0, 1.0);
    ColorEffectColor {
        red: (color.red as f32 * amount).round() as u16,
        green: (color.green as f32 * amount).round() as u16,
        blue: (color.blue as f32 * amount).round() as u16,
    }
}

fn spatial_palette_color(
    request: &ColorEffectRequest,
    position: f32,
    gradient_percent: f32,
) -> ColorEffectColor {
    let position = position.clamp(0.0, 1.0);
    let discrete = request
        .stops
        .iter()
        .rev()
        .find(|stop| stop.position <= position)
        .unwrap_or(&request.stops[0])
        .color;
    let gradient = (gradient_percent / 100.0).clamp(0.0, 1.0);
    if gradient <= f32::EPSILON {
        discrete
    } else {
        let continuous = evaluate_linear_stop_color(request, position);
        interpolate_color_effect_color(
            discrete,
            continuous,
            gradient,
            ColorEffectInterpolation::Rgb,
        )
    }
}

fn spatial_random_rank(cell: usize, cell_count: usize, seed: u64) -> usize {
    let key = splitmix64(seed ^ cell as u64);
    (0..cell_count)
        .filter(|candidate| {
            let candidate_key = splitmix64(seed ^ *candidate as u64);
            candidate_key < key || (candidate_key == key && *candidate < cell)
        })
        .count()
}

fn spatial_fractal_noise(x: f32, z: f32, octaves: u8, seed: u32) -> f32 {
    let mut value = 0.0;
    let mut weight = 0.5;
    let mut weight_sum = 0.0;
    let mut frequency = 1.0;
    for octave in 0..octaves {
        value +=
            spatial_value_noise(x * frequency, z * frequency, seed ^ u32::from(octave)) * weight;
        weight_sum += weight;
        frequency *= 2.0;
        weight *= 0.5;
    }
    if weight_sum <= f32::EPSILON {
        0.5
    } else {
        (value / weight_sum).clamp(0.0, 1.0)
    }
}

fn spatial_value_noise(x: f32, z: f32, seed: u32) -> f32 {
    let x0 = x.floor() as i32;
    let z0 = z.floor() as i32;
    let tx = x - x.floor();
    let tz = z - z.floor();
    let smooth = |value: f32| value * value * (3.0 - 2.0 * value);
    let sample = |sample_x: i32, sample_z: i32| {
        let mixed = (sample_x as u32).wrapping_mul(0x8DA6_B343)
            ^ (sample_z as u32).wrapping_mul(0xD816_3841)
            ^ seed;
        hash_unit_float(mixed)
    };
    let top = sample(x0, z0) + (sample(x0.saturating_add(1), z0) - sample(x0, z0)) * smooth(tx);
    let bottom = sample(x0, z0.saturating_add(1))
        + (sample(x0.saturating_add(1), z0.saturating_add(1)) - sample(x0, z0.saturating_add(1)))
            * smooth(tx);
    top + (bottom - top) * smooth(tz)
}

fn evaluate_cycle_color(request: &ColorEffectRequest, position: f32) -> ColorEffectColor {
    let stops = &request.stops;
    for pair in stops.windows(2) {
        if position >= pair[0].position && position < pair[1].position {
            let amount = (position - pair[0].position)
                / (pair[1].position - pair[0].position).max(f32::EPSILON);
            return interpolate_color_effect_color(
                pair[0].color,
                pair[1].color,
                amount,
                request.interpolation,
            );
        }
    }
    let first = &stops[0];
    let last = &stops[stops.len() - 1];
    let (from_position, to_position, sample_position) = if position < first.position {
        (last.position - 1.0, first.position, position)
    } else {
        (last.position, first.position + 1.0, position)
    };
    let distance = to_position - from_position;
    if distance <= f32::EPSILON {
        return first.color;
    }
    interpolate_color_effect_color(
        last.color,
        first.color,
        (sample_position - from_position) / distance,
        request.interpolation,
    )
}

fn evaluate_linear_stop_color(request: &ColorEffectRequest, position: f32) -> ColorEffectColor {
    let stops = &request.stops;
    if position <= stops[0].position {
        return stops[0].color;
    }
    for pair in stops.windows(2) {
        if position <= pair[1].position {
            let amount = (position - pair[0].position)
                / (pair[1].position - pair[0].position).max(f32::EPSILON);
            return interpolate_color_effect_color(
                pair[0].color,
                pair[1].color,
                amount,
                request.interpolation,
            );
        }
    }
    stops[stops.len() - 1].color
}

fn interpolate_color_effect_color(
    from: ColorEffectColor,
    to: ColorEffectColor,
    amount: f32,
    interpolation: ColorEffectInterpolation,
) -> ColorEffectColor {
    let amount = amount.clamp(0.0, 1.0);
    if matches!(interpolation, ColorEffectInterpolation::Rgb) {
        return ColorEffectColor {
            red: interpolate_u16(from.red, to.red, amount),
            green: interpolate_u16(from.green, to.green, amount),
            blue: interpolate_u16(from.blue, to.blue, amount),
        };
    }
    let (mut from_hue, from_saturation, from_value) = color_to_hsv(from);
    let (mut to_hue, to_saturation, to_value) = color_to_hsv(to);
    if from_saturation <= f32::EPSILON {
        from_hue = to_hue;
    }
    if to_saturation <= f32::EPSILON {
        to_hue = from_hue;
    }
    let mut delta = (to_hue - from_hue + 540.0).rem_euclid(360.0) - 180.0;
    if (delta + 180.0).abs() <= f32::EPSILON {
        delta = 180.0;
    }
    if matches!(interpolation, ColorEffectInterpolation::HsvLongest) {
        if delta.abs() <= f32::EPSILON {
            if from_saturation > f32::EPSILON && to_saturation > f32::EPSILON {
                delta = 360.0;
            }
        } else {
            delta = if delta > 0.0 {
                delta - 360.0
            } else {
                delta + 360.0
            };
        }
    }
    hsv_to_color(
        (from_hue + delta * amount).rem_euclid(360.0),
        from_saturation + (to_saturation - from_saturation) * amount,
        from_value + (to_value - from_value) * amount,
    )
}

fn color_to_hsv(color: ColorEffectColor) -> (f32, f32, f32) {
    let red = color.red as f32 / u16::MAX as f32;
    let green = color.green as f32 / u16::MAX as f32;
    let blue = color.blue as f32 / u16::MAX as f32;
    let max = red.max(green).max(blue);
    let min = red.min(green).min(blue);
    let delta = max - min;
    let hue = if delta <= f32::EPSILON {
        0.0
    } else if max == red {
        60.0 * ((green - blue) / delta).rem_euclid(6.0)
    } else if max == green {
        60.0 * ((blue - red) / delta + 2.0)
    } else {
        60.0 * ((red - green) / delta + 4.0)
    };
    let saturation = if max <= f32::EPSILON {
        0.0
    } else {
        delta / max
    };
    (hue.rem_euclid(360.0), saturation, max)
}

fn color_to_hsv_u16(color: ColorEffectColor) -> [u16; 3] {
    let (hue, saturation, value) = color_to_hsv(color);
    [
        ((hue / 360.0) * u16::MAX as f32).round() as u16,
        (saturation * u16::MAX as f32).round() as u16,
        (value * u16::MAX as f32).round() as u16,
    ]
}

fn hsv_to_color(hue: f32, saturation: f32, value: f32) -> ColorEffectColor {
    let saturation = saturation.clamp(0.0, 1.0);
    let value = value.clamp(0.0, 1.0);
    let chroma = value * saturation;
    let section = hue.rem_euclid(360.0) / 60.0;
    let x = chroma * (1.0 - (section.rem_euclid(2.0) - 1.0).abs());
    let (red, green, blue) = match section.floor() as u8 {
        0 => (chroma, x, 0.0),
        1 => (x, chroma, 0.0),
        2 => (0.0, chroma, x),
        3 => (0.0, x, chroma),
        4 => (x, 0.0, chroma),
        _ => (chroma, 0.0, x),
    };
    let offset = value - chroma;
    ColorEffectColor {
        red: ((red + offset) * u16::MAX as f32).round() as u16,
        green: ((green + offset) * u16::MAX as f32).round() as u16,
        blue: ((blue + offset) * u16::MAX as f32).round() as u16,
    }
}

fn blend_runtime_color(
    base: ColorEffectColor,
    effect: ColorEffectColor,
    blend_mode: &EffectBlendMode,
) -> ColorEffectColor {
    ColorEffectColor {
        red: blend_effect_value(base.red, effect.red, blend_mode),
        green: blend_effect_value(base.green, effect.green, blend_mode),
        blue: blend_effect_value(base.blue, effect.blue, blend_mode),
    }
}

fn nearest_runtime_color_wheel_value(
    slots: &[RuntimeColorWheelSlot],
    color: ColorEffectColor,
) -> Option<u16> {
    let target = color_to_oklab(color);
    slots
        .iter()
        .min_by(|left, right| {
            oklab_distance_squared(left.oklab, target)
                .total_cmp(&oklab_distance_squared(right.oklab, target))
                .then_with(|| left.dmx_value.cmp(&right.dmx_value))
        })
        .map(|slot| slot.dmx_value)
}

fn color_to_oklab(color: ColorEffectColor) -> [f32; 3] {
    fn linear(value: u16) -> f32 {
        let value = value as f32 / u16::MAX as f32;
        if value <= 0.040_45 {
            value / 12.92
        } else {
            ((value + 0.055) / 1.055).powf(2.4)
        }
    }
    let red = linear(color.red);
    let green = linear(color.green);
    let blue = linear(color.blue);
    let l = (0.412_221_46 * red + 0.536_332_55 * green + 0.051_445_995 * blue).cbrt();
    let m = (0.211_903_5 * red + 0.680_699_5 * green + 0.107_396_96 * blue).cbrt();
    let s = (0.088_302_46 * red + 0.281_718_85 * green + 0.629_978_7 * blue).cbrt();
    [
        0.210_454_26 * l + 0.793_617_8 * m - 0.004_072_047 * s,
        1.977_998_5 * l - 2.428_592_2 * m + 0.450_593_7 * s,
        0.025_904_037 * l + 0.782_771_77 * m - 0.808_675_77 * s,
    ]
}

fn oklab_distance_squared(left: [f32; 3], right: [f32; 3]) -> f32 {
    left.iter()
        .zip(right)
        .map(|(left, right)| (left - right).powi(2))
        .sum()
}

fn splitmix64(mut value: u64) -> u64 {
    value = value.wrapping_add(0x9e37_79b9_7f4a_7c15);
    let mut mixed = value;
    mixed = (mixed ^ (mixed >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
    mixed = (mixed ^ (mixed >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
    mixed ^ (mixed >> 31)
}

fn dmx_preview_to_frame(preview: &[u8]) -> [u8; 512] {
    let mut frame = [0u8; 512];
    let len = preview.len().min(frame.len());
    frame[..len].copy_from_slice(&preview[..len]);
    frame
}

fn dmx_previews_to_frames(previews: &[DmxUniversePreview]) -> HashMap<u16, [u8; 512]> {
    previews
        .iter()
        .map(|preview| (preview.universe, dmx_preview_to_frame(&preview.values)))
        .collect()
}

fn blend_effect_value(base: u16, effect: u16, blend_mode: &EffectBlendMode) -> u16 {
    match blend_mode {
        EffectBlendMode::Override => effect,
        EffectBlendMode::Add => base.saturating_add(effect),
        EffectBlendMode::Multiply => ((base as u32 * effect as u32) / 65_535) as u16,
    }
}

fn blend_effect_float(base: f32, effect: f32, blend_mode: &EffectBlendMode) -> f32 {
    match blend_mode {
        EffectBlendMode::Override => effect,
        EffectBlendMode::Add => base + effect,
        EffectBlendMode::Multiply => base * effect,
    }
}

