    #[test]
    fn published_node_graph_remove_rolls_back_graph_and_cue_when_snapshot_is_busy() {
        let mut runtime = EngineRuntime::new(DmxOutputConfig::default());
        runtime.node_graphs.push(runtime_node_graph_from_summary(
            sample_node_graph(1, 1),
            Instant::now(),
        ));
        let cue = CueSummary {
            id: 1,
            label: "Audio cue".to_string(),
            node_graph_targets: vec![CueNodeGraphTarget {
                graph_id: 1,
                enabled: true,
            }],
            ..CueSummary::default()
        };
        runtime.cues.push(runtime_cue_from_summary(&cue));
        runtime.last_error = Some("previous".to_string());

        let snapshot = RwLock::new(EngineSnapshot::default());
        let read_guard = snapshot.read().unwrap();
        let (ack, receiver) = mpsc::sync_channel(1);
        runtime.apply_command(EngineCommand::RemoveNodeGraphPublished {
            graph_id: 1,
            expires_at: Instant::now() + Duration::from_secs(1),
            ack,
        });
        assert!(runtime.node_graphs.is_empty());
        assert!(runtime.cues[0].node_graph_targets.is_empty());

        runtime.publish_pending_command_acks(0, &snapshot);
        assert!(receiver
            .recv_timeout(Duration::from_millis(50))
            .unwrap()
            .is_err());
        assert_eq!(runtime.node_graphs.len(), 1);
        assert_eq!(runtime.cues[0].node_graph_targets[0].graph_id, 1);
        assert_eq!(runtime.last_error.as_deref(), Some("previous"));
        drop(read_guard);
    }

    #[test]
    fn live_audio_spectrum_expires_inside_the_engine_at_the_ttl_boundary() {
        let mut runtime = EngineRuntime::new(DmxOutputConfig::default());
        let updated_at = Instant::now();
        add_runtime_test_video_layer(&mut runtime, 1, VideoLayerState::default());
        runtime
            .set_auto_vj_config(AutoVjConfig {
                eligible_layer_ids: vec![1],
                seed: 0,
                beats_per_change: 1,
                transition_ms: 0,
                avoid_immediate_repeat: true,
                rhythm_source: AutoVjRhythmSource::LiveAudio,
            })
            .unwrap();
        runtime.set_auto_vj_armed(true, updated_at).unwrap();
        runtime.live_audio_spectrum = Some(AudioSpectrumPoint {
            time_ms: 0,
            bass: 0.1,
            mid: 0.75,
            high: 0.2,
        });
        runtime.live_audio_spectrum_updated_at = Some(updated_at);

        assert!(!runtime.expire_live_audio_spectrum(
            updated_at + LIVE_AUDIO_SPECTRUM_TTL - Duration::from_nanos(1)
        ));
        assert!(runtime.live_audio_spectrum.is_some());
        assert!(runtime.expire_live_audio_spectrum(updated_at + LIVE_AUDIO_SPECTRUM_TTL));
        assert!(runtime.live_audio_spectrum.is_none());
        assert!(runtime.live_audio_spectrum_updated_at.is_none());
        assert_eq!(runtime.auto_vj.status.mode, AutoVjMode::Hold);
        assert!(runtime.auto_vj.status.hold);
    }

