    #[test]
    fn cue_can_trigger_video_layer_state() {
        let engine = EngineHandle::start(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        let layer_id = engine.allocate_video_layer_id();
        engine
            .send(EngineCommand::AddVideoLayer {
                layer_id,
                label: "Layer 1".to_string(),
                source: VideoSourceSummary {
                    kind: protocol::VideoSourceKind::File,
                    path: Some("memory://clip.mp4".to_string()),
                    name: None,
                    codec: Some("H264".to_string()),
                    metadata: None,
                },
            })
            .unwrap();
        let cue_id = engine.allocate_cue_id();
        engine
            .send(EngineCommand::CreateCue {
                authored_beats: None,
                cue_id,
                label: "Video Cue".to_string(),
                fade_ms: 0,
                targets: Vec::new(),
                video_targets: vec![VideoLayerTarget {
                    layer_id,
                    state: VideoLayerState {
                        enabled: true,
                        solo: false,
                        opacity: 0.5,
                        speed: 2.0,
                        playing: true,
                        position_ms: 1_000,
                        loop_enabled: true,
                        loop_start_ms: 500,
                        loop_end_ms: 2_000,
                        bpm_sync: Default::default(),
                        cue_points: Vec::new(),
                        cue_points_ms: Vec::new(),
                        transform: Default::default(),
                        color: Default::default(),
                        fx: Default::default(),
                    },
                }],
                video_output_targets: Vec::new(),

                node_graph_targets: Vec::new(),
                effect_targets: Vec::new(),
            })
            .unwrap();
        engine.send(EngineCommand::TriggerCue(cue_id)).unwrap();

        let mut snapshot = engine.snapshot();
        for _ in 0..20 {
            if snapshot
                .video
                .layers
                .first()
                .map(|layer| layer.state.playing)
                == Some(true)
            {
                break;
            }
            std::thread::sleep(DMX_TICK_INTERVAL);
            snapshot = engine.snapshot();
        }

        let layer = snapshot.video.layers.first().unwrap();
        assert_eq!(snapshot.cues[0].video_targets.len(), 1);
        assert_eq!(snapshot.cues[0].video_targets[0].state.position_ms, 1_000);
        assert_eq!(layer.id, layer_id);
        assert_eq!(layer.state.opacity, 0.5);
        assert_eq!(layer.state.speed, 2.0);
        assert!(layer.state.playing);
        assert!((500..=2_000).contains(&layer.state.position_ms));
    }

    #[test]
    fn duplicate_video_layer_copies_state_and_composition_membership() {
        let engine = EngineHandle::start(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        let source_layer_id = engine.allocate_video_layer_id();
        engine
            .send(EngineCommand::AddVideoLayer {
                layer_id: source_layer_id,
                label: "Source".to_string(),
                source: VideoSourceSummary {
                    kind: protocol::VideoSourceKind::File,
                    path: Some("memory://clip.mp4".to_string()),
                    name: None,
                    codec: Some("H264".to_string()),
                    metadata: None,
                },
            })
            .unwrap();
        engine
            .send(EngineCommand::SetVideoLayerBlendMode {
                layer_id: source_layer_id,
                blend_mode: VideoBlendMode::Add,
            })
            .unwrap();
        engine
            .send(EngineCommand::SetVideoLayerState {
                layer_id: source_layer_id,
                state: VideoLayerState {
                    opacity: 0.42,
                    speed: 2.0,
                    playing: true,
                    ..VideoLayerState::default()
                },
            })
            .unwrap();
        let isf_effect = VideoIsfEffectSummary {
            enabled: true,
            label: "Threshold".to_string(),
            source: "/*{\"INPUTS\":[{\"NAME\":\"inputImage\",\"TYPE\":\"image\"}]}*/ void main(){ gl_FragColor = IMG_THIS_PIXEL(inputImage); }".into(),
            source_path: Some("filters/threshold.fs".to_string()),
            description: Some("Test filter".to_string()),
            categories: vec!["Test".to_string()],
            controls: Vec::new(),
            stack: vec![
                VideoIsfEffectStageSummary {
                    enabled: false,
                    label: "Invert".to_string(),
                    source: "/*{\"INPUTS\":[{\"NAME\":\"inputImage\",\"TYPE\":\"image\"}]}*/ void main(){ gl_FragColor = vec4(1.0) - IMG_THIS_PIXEL(inputImage); }".into(),
                    source_path: Some("filters/invert.fs".to_string()),
                    description: Some("Disabled tail stage".to_string()),
                    categories: vec!["Color".to_string()],
                    controls: vec![protocol::VideoIsfControlSummary {
                        name: "amount".to_string(),
                        kind: VideoIsfControlKind::Float,
                        value: [0.25, 0.0, 0.0, 0.0],
                        default: [1.0, 0.0, 0.0, 0.0],
                        minimum: [0.0; 4],
                        maximum: [1.0; 4],
                        labels: Vec::new(),
                        values: Vec::new(),
                    }],
                },
                VideoIsfEffectStageSummary {
                    enabled: true,
                    label: "Posterize".to_string(),
                    source: "/*{\"INPUTS\":[{\"NAME\":\"inputImage\",\"TYPE\":\"image\"}]}*/ void main(){ gl_FragColor = IMG_THIS_PIXEL(inputImage); }".into(),
                    source_path: Some("filters/posterize.fs".to_string()),
                    description: Some("Enabled tail stage".to_string()),
                    categories: vec!["Stylize".to_string()],
                    controls: vec![protocol::VideoIsfControlSummary {
                        name: "levels".to_string(),
                        kind: VideoIsfControlKind::Long,
                        value: [6.0, 0.0, 0.0, 0.0],
                        default: [4.0, 0.0, 0.0, 0.0],
                        minimum: [2.0, 0.0, 0.0, 0.0],
                        maximum: [32.0, 0.0, 0.0, 0.0],
                        labels: Vec::new(),
                        values: Vec::new(),
                    }],
                },
            ],
        };
        engine
            .send(EngineCommand::SetVideoLayerIsfEffect {
                layer_id: source_layer_id,
                effect: Some(isf_effect.clone()),
            })
            .unwrap();
        engine
            .send(EngineCommand::AddVideoComposition(CompositionSummary {
                id: 2,
                label: "Aux".to_string(),
                layer_ids: vec![source_layer_id],
                output_ids: Vec::new(),
            }))
            .unwrap();

        let duplicate_layer_id = engine.allocate_video_layer_id();
        engine
            .send(EngineCommand::DuplicateVideoLayer {
                source_layer_id,
                new_layer_id: duplicate_layer_id,
                label: "  Copy  ".to_string(),
            })
            .unwrap();
        engine
            .send(EngineCommand::SetVideoLayerLabel {
                layer_id: duplicate_layer_id,
                label: "  Renamed Copy  ".to_string(),
            })
            .unwrap();

        let mut snapshot = engine.snapshot();
        for _ in 0..20 {
            if snapshot.video.layers.len() == 2
                && snapshot
                    .video
                    .layers
                    .iter()
                    .any(|layer| layer.id == duplicate_layer_id && layer.label == "Renamed Copy")
            {
                break;
            }
            std::thread::sleep(DMX_TICK_INTERVAL);
            snapshot = engine.snapshot();
        }

        assert_eq!(
            snapshot
                .video
                .layers
                .iter()
                .map(|layer| layer.id)
                .collect::<Vec<_>>(),
            vec![source_layer_id, duplicate_layer_id]
        );
        let duplicate = snapshot
            .video
            .layers
            .iter()
            .find(|layer| layer.id == duplicate_layer_id)
            .unwrap();
        assert_eq!(duplicate.label, "Renamed Copy");
        assert_eq!(duplicate.source.path.as_deref(), Some("memory://clip.mp4"));
        assert_eq!(duplicate.source.codec.as_deref(), Some("H264"));
        assert_eq!(duplicate.blend_mode, VideoBlendMode::Add);
        assert_eq!(duplicate.state.opacity, 0.42);
        assert_eq!(duplicate.state.speed, 2.0);
        assert!(duplicate.state.playing);
        let duplicate_effect = duplicate.isf_effect.as_ref().unwrap();
        assert_eq!(
            duplicate_effect
                .stack
                .iter()
                .map(|stage| stage.label.as_str())
                .collect::<Vec<_>>(),
            vec!["Invert", "Posterize"]
        );
        assert!(!duplicate_effect.stack[0].enabled);
        assert_eq!(duplicate_effect.stack[0].controls[0].value[0], 0.25);
        assert!(duplicate_effect.stack[1].enabled);
        assert_eq!(duplicate_effect.stack[1].controls[0].value[0], 6.0);
        assert_eq!(duplicate.isf_effect, Some(isf_effect));
        let aux = snapshot
            .video
            .compositions
            .iter()
            .find(|composition| composition.id == 2)
            .unwrap();
        assert_eq!(aux.layer_ids, vec![source_layer_id, duplicate_layer_id]);
    }

