    #[test]
    fn identity_colors_set_clear_and_survive_snapshot_roundtrip() {
        let engine = EngineHandle::start(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });

        let mut cue = CueSummary::default();
        cue.id = 5;
        cue.cue_number = "1".to_string();
        cue.label = "Colored".to_string();
        cue.group_id = Some("Front".to_string());
        let mut snapshot = EngineSnapshot::default();
        snapshot.cues = vec![cue];
        snapshot.output.enabled = false;
        snapshot.dmx_outputs = vec![snapshot.output.clone()];
        engine
            .send(EngineCommand::LoadProjectSnapshot(snapshot))
            .unwrap();
        for _ in 0..100 {
            if engine.snapshot().cues.len() == 1 {
                break;
            }
            thread::sleep(Duration::from_millis(10));
        }

        engine
            .set_cue_color_published(5, Some("#ff3366".to_string()))
            .unwrap();
        engine
            .set_group_color_published("Front".to_string(), Some("#22aa88".to_string()))
            .unwrap();
        let colored = engine.snapshot();
        assert_eq!(colored.cues[0].color.as_deref(), Some("#ff3366"));
        assert_eq!(
            colored.group_colors.get("Front").map(String::as_str),
            Some("#22aa88")
        );

        // The colors are project data: a save/load roundtrip preserves them.
        engine
            .send(EngineCommand::LoadProjectSnapshot(colored.clone()))
            .unwrap();
        let mut reloaded = engine.snapshot();
        for _ in 0..100 {
            if reloaded
                .cues
                .first()
                .and_then(|cue| cue.color.clone())
                .is_some()
            {
                break;
            }
            thread::sleep(Duration::from_millis(10));
            reloaded = engine.snapshot();
        }
        assert_eq!(reloaded.cues[0].color.as_deref(), Some("#ff3366"));
        assert_eq!(
            reloaded.group_colors.get("Front").map(String::as_str),
            Some("#22aa88")
        );

        // Clearing removes the persisted values again.
        engine.set_cue_color_published(5, None).unwrap();
        engine
            .set_group_color_published("Front".to_string(), None)
            .unwrap();
        let cleared = engine.snapshot();
        assert!(cleared.cues[0].color.is_none());
        assert!(cleared.group_colors.is_empty());

        // Unknown cue ids fail the ack instead of silently succeeding.
        assert!(engine
            .set_cue_color_published(999, Some("#ffffff".to_string()))
            .is_err());
    }

    #[test]
    fn large_show_loads_200_fixtures_across_8_universes_and_100_cues() {
        let engine = EngineHandle::start(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        let fixtures = (0..200u64)
            .map(|index| {
                let mut fixture = sample_patched_fixture(
                    index + 1,
                    &format!("Stress Fixture {}", index + 1),
                    ((index % 25) * 4 + 1) as u16,
                );
                fixture.universe = (index / 25) as u16;
                fixture.position = Vec3 {
                    x: (index % 25) as f32 - 12.0,
                    y: 4.0,
                    z: (index / 25) as f32 - 3.5,
                };
                fixture
            })
            .collect::<Vec<_>>();
        let cues = (0..100u64)
            .map(|cue_index| CueSummary {
                id: cue_index + 1,
                label: format!("Stress Cue {}", cue_index + 1),
                fade_ms: 250,
                targets: fixtures
                    .iter()
                    .map(|fixture| CueFixtureTarget {
                        fixture_id: fixture.id,
                        values: vec![AttributeValueSummary {
                            attribute: "Dimmer".to_string(),
                            value: ((cue_index * 661) % 65_536) as u16,
                        }],
                    })
                    .collect(),
                video_targets: Vec::new(),
                video_output_targets: Vec::new(),
                node_graph_targets: Vec::new(),
                ..CueSummary::default()
            })
            .collect::<Vec<_>>();
        let mut snapshot = EngineSnapshot::default();
        snapshot.fixtures = fixtures;
        snapshot.cues = cues;
        snapshot.output.enabled = false;
        snapshot.dmx_outputs = vec![snapshot.output.clone()];

        let load_started = Instant::now();
        engine
            .send(EngineCommand::LoadProjectSnapshot(snapshot))
            .unwrap();
        let mut loaded = engine.snapshot();
        for _ in 0..100 {
            if loaded.fixtures.len() == 200 && loaded.cues.len() == 100 {
                break;
            }
            std::thread::sleep(Duration::from_millis(10));
            loaded = engine.snapshot();
        }
        let load_elapsed = load_started.elapsed();
        assert_eq!(loaded.fixtures.len(), 200);
        assert_eq!(loaded.cues.len(), 100);
        assert!(
            load_elapsed < Duration::from_secs(2),
            "large show load took {load_elapsed:?}"
        );

        engine.send(EngineCommand::TriggerCue(100)).unwrap();
        for _ in 0..100 {
            loaded = engine.snapshot();
            if loaded.active_cue_id == Some(100) && loaded.dmx_previews.len() >= 8 {
                break;
            }
            std::thread::sleep(Duration::from_millis(10));
        }
        assert_eq!(loaded.active_cue_id, Some(100));
        assert_eq!(loaded.dmx_previews.len(), 8);
        assert!(loaded
            .dmx_previews
            .iter()
            .all(|preview| preview.values.len() == 512));
        assert_eq!(loaded.telemetry.queue_push_failure_count, 0);
        assert_eq!(loaded.telemetry.command_drain_limit_hit_count, 0);
    }

