    fn runtime_with_mixed_effect_fixtures(count: u64) -> EngineRuntime {
        let mut runtime = EngineRuntime::new(DmxOutputConfig {
            enabled: false,
            ..DmxOutputConfig::default()
        });
        let mut profile = sample_profile();
        profile.dmx_modes[0].controls.push(AttributeControl {
            attribute: "Tilt".to_string(),
            channel_name: "Tilt".to_string(),
            geometry: None,
            offsets: vec![4, 5],
            resolution: AttributeResolution::SixteenBit,
            default_value: 0,
            functions: Vec::new(),
        });
        profile.dmx_modes[0]
            .controls
            .push(test_color_control("ColorRed", 6));
        profile.dmx_modes[0]
            .controls
            .push(test_color_control("ColorGreen", 7));
        profile.dmx_modes[0]
            .controls
            .push(test_color_control("ColorBlue", 8));
        for fixture_id in 1..=count {
            let zero_based = fixture_id - 1;
            let mut request = sample_patch_request(
                &format!("Mixed {fixture_id}"),
                1 + ((zero_based % 64) as u16) * 8,
            );
            request.universe = (zero_based / 64) as u16;
            request.group_ids = vec!["Mixed".to_string()];
            runtime.apply_command(EngineCommand::PatchFixture {
                fixture_id,
                request,
                profile: profile.clone(),
            });
        }
        assert_eq!(runtime.last_error, None);
        assert!(runtime
            .fixtures
            .iter()
            .all(|fixture| fixture.color_binding.is_some()));
        runtime
    }

    #[test]
    fn mixed_color_chaser_move_curve_mapping_and_color_mapping_release_stack_meets_44hz_budget() {
        const FIXTURE_COUNT: u64 = 200;
        const EFFECT_COUNT: usize = 64;
        const SAMPLES: usize = 1_000;
        const ATTRIBUTES: [&str; 6] = [
            "Dimmer",
            "ColorRed",
            "ColorGreen",
            "ColorBlue",
            "Pan",
            "Tilt",
        ];

        let mut runtime = runtime_with_mixed_effect_fixtures(FIXTURE_COUNT);
        let fixture_ids = (1..=FIXTURE_COUNT).collect::<Vec<_>>();
        let created_at = Instant::now();
        let mut chaser_base = test_chaser_request(&fixture_ids);
        chaser_base.active_step_count = 4;
        chaser_base.wings = 2;
        chaser_base.duty_cycle = 0.75;
        chaser_base.overlap = 0.25;
        chaser_base.fixture_spread = 0.5;
        let move_base = test_move_request(&fixture_ids);
        let curve_base = test_curve_request(&fixture_ids);
        let mapping_base = test_mapping_request(&fixture_ids);
        let color_mapping_base = test_color_mapping_request(fixture_ids.clone());
        for index in 0..EFFECT_COUNT {
            let phase = index as f32 / EFFECT_COUNT as f32;
            let kind = match index % 6 {
                0 => {
                    let mut request = test_color_request(
                        fixture_ids.clone(),
                        test_color(
                            ((index + 1) * 977) as u16,
                            ((index + 1) * 431) as u16,
                            ((index + 1) * 211) as u16,
                        ),
                    );
                    request.stops.insert(
                        1,
                        protocol::ColorEffectStop {
                            position: 0.5,
                            color: test_color(
                                ((index + 7) * 613) as u16,
                                ((index + 3) * 389) as u16,
                                ((index + 5) * 149) as u16,
                            ),
                        },
                    );
                    request.algorithm = ColorEffectAlgorithm::Cycle;
                    request.interpolation = ColorEffectInterpolation::HsvShortest;
                    request.fixture_spread = 1.0;
                    request.phase = phase;
                    RuntimeEffectKind::Color(runtime.resolve_color_effect_request(request).unwrap())
                }
                1 => {
                    let mut request = chaser_base.clone();
                    request.phase = phase;
                    RuntimeEffectKind::Chaser(
                        runtime.resolve_chaser_effect_request(request).unwrap(),
                    )
                }
                2 => {
                    let mut request = move_base.clone();
                    request.phase = phase;
                    RuntimeEffectKind::Move(runtime.resolve_move_effect_request(request).unwrap())
                }
                3 => {
                    let mut request = curve_base.clone();
                    request.phase = phase;
                    RuntimeEffectKind::Curve(runtime.resolve_curve_effect_request(request).unwrap())
                }
                4 => {
                    let mut request = mapping_base.clone();
                    request.phase = phase;
                    request.repetitions = 1.0 + (index % 4) as f32;
                    RuntimeEffectKind::Mapping(
                        runtime.resolve_mapping_effect_request(request).unwrap(),
                    )
                }
                _ => {
                    let mut request = color_mapping_base.clone();
                    request.phase = phase;
                    request.offset_u = index as f32 / EFFECT_COUNT as f32;
                    request.sampling = ColorMappingSampling::Bilinear;
                    RuntimeEffectKind::ColorMapping(
                        runtime
                            .resolve_color_mapping_effect_request(request)
                            .unwrap(),
                    )
                }
            };
            runtime.effects.push(RuntimeEffect {
                id: index as EffectId + 1,
                kind,
                enabled: true,
                created_at,
            });
        }

        let mut durations = Vec::with_capacity(SAMPLES);
        let mut checksum = 0_u64;
        for sample in 0..SAMPLES {
            let at = created_at + DMX_TICK_INTERVAL * (sample as u32 + 1);
            let started = Instant::now();
            for fixture in &runtime.fixtures {
                for attribute in ATTRIBUTES {
                    checksum =
                        checksum.wrapping_add(runtime.apply_effects_with_transition_policy(
                            fixture, attribute, 16_384, at, false,
                        ) as u64);
                }
            }
            durations.push(started.elapsed());
        }
        std::hint::black_box(checksum);
        assert_ne!(checksum, 0);
        durations.sort_unstable();
        let p95 = durations[(SAMPLES * 95 / 100).min(SAMPLES - 1)];
        let p99 = durations[(SAMPLES * 99 / 100).min(SAMPLES - 1)];
        let max = *durations.last().unwrap();
        eprintln!(
            "Mixed Color/Chaser/Move/Curve/Mapping/ColorMapping 64x200 stack per-tick evaluation: p95={}us p99={}us max={}us",
            p95.as_micros(),
            p99.as_micros(),
            max.as_micros()
        );
        // Budget rationale: this measures the true production per-tick path
        // (apply_effects per fixture x control, including its per-call clock
        // snapshot) under 64 simultaneous full-rig effects. Observed on the
        // reference Windows host in release with Curve included: p95 ~2.8ms /
        // p99 ~3.4ms / max ~4.1ms. Mapping and Colour Mapping are included and
        // must remain within the same gate, which keeps the worst-case mixed stack at or below
        // roughly half of the 22.7ms 44Hz tick while still failing on a
        // >50% evaluation regression.
        if !cfg!(debug_assertions) {
            assert!(p95 <= Duration::from_millis(5), "p95 was {p95:?}");
            assert!(p99 <= Duration::from_millis(8), "p99 was {p99:?}");
            assert!(max <= Duration::from_millis(12), "max was {max:?}");
        }

        // T19-D worst-case transition path: every active Effect evaluates an
        // outgoing and incoming Cue-owned state. The activation list and both
        // runtimes are prebuilt here exactly as they are at Cue trigger time;
        // the measured 44 Hz path performs no lookup or allocation.
        const TRANSITION_SAMPLES: usize = if cfg!(debug_assertions) { 20 } else { 200 };
        runtime.effect_activations = runtime
            .effects
            .iter()
            .cloned()
            .map(|effect| RuntimeEffectActivation {
                transition: Some(RuntimeEffectTransition {
                    from: effect.clone(),
                    from_rate: 1.0,
                    started_at: created_at,
                    duration: Duration::from_secs(60),
                    progress_cache: Cell::new(None),
                }),
                effect,
                key: Some(RuntimeEffectActivationKey::CueList {
                    cue_list_id: DEFAULT_CUE_LIST_ID,
                    cue_id: 1,
                }),
                rate: 1.0,
                transition_ms: Some(60_000),
            })
            .collect();
        runtime.active_effect_activation_indices = (0..runtime.effect_activations.len()).collect();
        runtime.effects.clear();
        let mut transition_durations = Vec::with_capacity(TRANSITION_SAMPLES);
        let mut transition_checksum = 0_u64;
        for sample in 0..TRANSITION_SAMPLES {
            let at = created_at + DMX_TICK_INTERVAL * (sample as u32 + 1);
            let started = Instant::now();
            for fixture in &runtime.fixtures {
                for attribute in ATTRIBUTES {
                    transition_checksum = transition_checksum.wrapping_add(
                        runtime.apply_effects_with_transition_policy(
                            fixture, attribute, 16_384, at, false,
                        ) as u64,
                    );
                }
            }
            transition_durations.push(started.elapsed());
        }
        std::hint::black_box(transition_checksum);
        assert_ne!(transition_checksum, 0);
        transition_durations.sort_unstable();
        let transition_p95 =
            transition_durations[(TRANSITION_SAMPLES * 95 / 100).min(TRANSITION_SAMPLES - 1)];
        let transition_p99 =
            transition_durations[(TRANSITION_SAMPLES * 99 / 100).min(TRANSITION_SAMPLES - 1)];
        let transition_max = *transition_durations.last().unwrap();
        eprintln!(
            "Cue transition mixed 64x200 stack per-tick evaluation: p95={}us p99={}us max={}us",
            transition_p95.as_micros(),
            transition_p99.as_micros(),
            transition_max.as_micros()
        );
        // This intentionally doubles every one of the 64 full-rig Effect
        // evaluations, a much harsher case than an ordinary Cue change. Keep
        // p95 near half of the 22.7ms tick and even the maximum inside one
        // tick, without relaxing the established non-transition 5/8/12 gate.
        if !cfg!(debug_assertions) {
            assert!(
                transition_p95 <= Duration::from_millis(12),
                "transition p95 was {transition_p95:?}"
            );
            assert!(
                transition_p99 <= Duration::from_millis(16),
                "transition p99 was {transition_p99:?}"
            );
            assert!(
                transition_max <= Duration::from_millis(20),
                "transition max was {transition_max:?}"
            );
        }
    }

    #[test]
    fn legacy_timeline_event_update_preserves_scene_block_extension_fields() {
        let mut runtime = runtime_with_lfo_effects(&[(1, false)]);
        create_effect_only_cue(
            &mut runtime,
            1,
            vec![CueEffectTarget {
                effect_id: 1,
                enabled: true,
                params: None,
                transition_ms: None,
            }],
        );
        runtime.timeline_events.push(RuntimeTimelineEvent {
            time_beats: None,
            duration_beats: None,
            conform_to_tempo: false,
            loop_fill: false,
            fade_in_ms: 0,
            fade_out_ms: 0,
            iteration_period_ms: 0,
            rate: None,
            id: 10,
            cue_id: 1,
            time_ms: 100,
            track: TimelineTrackKind::Lighting,
            layer_id: None,
            resolved_layer_id: 0,
            layer_order: 0,
            layer_muted_effective: false,
            duration_ms: 500,
            loop_count: 4,
            jump_to_event_id: Some(10),
        });

        runtime.apply_command(EngineCommand::SetTimelineCueEvent {
            time_beats: None,
            event_id: 10,
            cue_id: 1,
            time_ms: 250,
            track: TimelineTrackKind::Video,
            layer_id: None,
        });

        let updated = &runtime.timeline_events[0];
        assert_eq!(updated.time_ms, 250);
        assert_eq!(updated.track, TimelineTrackKind::Video);
        assert_eq!(updated.duration_ms, 500);
        assert_eq!(updated.loop_count, 4);
        assert_eq!(updated.jump_to_event_id, Some(10));

        runtime.apply_command(EngineCommand::AddTimelineCueEvent {
            time_beats: None,
            event_id: 11,
            cue_id: 1,
            time_ms: 300,
            track: TimelineTrackKind::Lighting,
            layer_id: None,
        });
        let point = runtime
            .timeline_events
            .iter()
            .find(|event| event.id == 11)
            .unwrap();
        assert_eq!(point.duration_ms, 0);
        assert_eq!(point.loop_count, 1);
        assert_eq!(point.jump_to_event_id, None);
    }

